window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_001"]={"n":"李俊民","dyn":"元","poems":[{"t":"过云台","f":"七言绝句","c":["夜半风吹霁色开，晓乘残月过云台。","连山断处瞰平野，一线黄流掌上来。"]},{"t":"雨后","f":"七言绝句","c":["春空霭霭暮云低，飞过山前雨一犁。","明日却寻归去路，马蹄犹踏落花泥。"]},{"t":"太常引 刘君祥寿二月十五日","f":"曲","c":["区区州县肯徒劳。","谁得似、卯金刀。","一笑醉蟠桃。","问何处、仙山可巢。","两朝人物，积年阴德，心力过萧曹。","门户便须高。","看今后、君家凤毛。"]},{"t":"太常引 同知崔仲明生日","f":"曲","c":["太行千里政声扬。","问何处、是黄堂。","遗爱几时忘。","试听取、人歌召棠。","锦衣年少，插花跃马，休负好风光。","三万六千场。","但暮暮、朝朝醉乡。"]},{"t":"太常引 窦君瑞寿日","f":"曲","c":["燕山勋烈有馀光。","问丹桂、几枝芳。","阴德后来昌。","但教子、应须义方。","功名看破，黄冠野服，林下道家装。","何处是仙乡。","这日月、闲中最长。"]},{"t":"水龙吟 筹堂寿日","f":"曲","c":["一朝衣锦归来，高门不负于公望。","恍然如旧，黄流万里，太行千丈。","只比当时，添些气势，减些风浪。","记采薇戍罢，分茅议定，凯歌动、声悲壮。","元自山西出将。","却从他、山东入相。","兜鍪须待，貂蝉换了，凌烟画像。","且把功名，暂都分付，浅斟低唱。","但年年、看取三台长在，老人头上。"]},{"t":"水龙吟 翟端甫寿日十月一日","f":"曲","c":["胜游漫说山阴，算来不及山阳好。","七贤林下，一时人物，何如安道。","况有奇才，纵横笔阵，千军独埽。","向碧油幢底，真儒事业，倚马看、檄书草。","谁识平居隐操。","遇江州、十分礼貌。","世情交态，雀罗门外，几人曾到。","且斗樽前，等闲休问，高山白早。","赖姮娥，留得一枝丹桂，伴灵椿老。"]},{"t":"西江月 张堂臣寿日","f":"曲","c":["人比当年杨柳，六郎元似莲花。","渔经猎史是生涯。","那羡章台走马。","鲈脍未归夙驾，斗牛尚客星槎。","直教三战过崔家。","伴取赤松林下。"]},{"t":"西江月 答亚之","f":"曲","c":["漠漠烟生碧树，溶溶水满芳溪。","东风吹湿落花泥。","忙杀营巢燕子。","百字诗惭我寄，一壶酒望君携。","休将闲事等闲题。","且把眉头放起。"]},{"t":"西江月 筹堂寿","f":"曲","c":["落落琼林人物，飘飘鹤氅仙风。","渡江已后见英雄。","那在悬刀一梦。","雾恰山中隐豹，云还天上从龙。","太行直枕大河东。","犹比声名不重。"]},{"t":"西江月 裴节度使寿（字怀诚）","f":"曲","c":["荐疏李誇精鉴，婿佳韦得贤侯。","手如霹雳在同州。","不让当时谈薮。","但可称为劲草，莫教指作清流。","归来绿野任沉浮。","这个家风耐久。"]},{"t":"阮郎归 戏李子搢","f":"曲","c":["江南江北水连云。","江山憔悴人。","华簪犹拂洛阳尘。","离筵何太频。","歌近耳，酒盈樽。","樽前见在身。","昨朝骂坐灌将军。","近前丞相嗔。"]},{"t":"阮郎归 杨彦明寿日筹堂之甥","f":"曲","c":["年来宅相有谁承。","人誇似舅甥。","带牛佩犊尽春耕。","菟裘了一生。","闲事业，寄丹青。","笔端如有神。","试看自写镜中真。","老人南极星。"]},{"t":"阮郎归 郭延年诞日","f":"曲","c":["断蓬踪迹去依刘。","试登王粲楼。","此心安处即菟裘。","尚何来往求。","诗遣兴，酒消愁。","竹林多胜游。","与君何日共仙舟。","相看应白头。"]},{"t":"南乡子 上夫人寿日","f":"曲","c":["香霭博山炉。","罗绮森森奉燕居。","昼锦归来冠盖里，当时。","曾拜金花大国书。","一旦得双珠。","阿大中郎喜有馀。","见说上天虽富贵，争如。","平地仙家碧玉壶。"]},{"t":"南乡子 李克绍生朝","f":"曲","c":["来往亦风流。","曾伴仙翁衣锦游。","闻道长平朱紫地，西楼。","依旧人人说故侯。","能得几春秋。","未必灵椿老便休。","自有枝枝丹桂在，何忧。","宝月忙催玉斧修。"]},{"t":"南乡子 锦堂寿日","f":"曲","c":["弓剑不离身。","唾手功名马上成。","见说人生为郡乐，班春。","政事如棋局局新。","熊梦庆佳辰。","喜动山城击壤民。","昼锦堂前争献寿，留宾。","尽是蟠桃会上人。"]},{"t":"南乡子 锦堂碧落寿席","f":"曲","c":["爽气逼人寒。","相对溪堂雪后山。","赖有忘年林下友，盘桓。","都把功名付等闲。","尽道好休官。","况在黄柑紫蟹閒。","天意不随人事改，平安。","愁莫能侵镜里颜。"]},{"t":"洞仙歌 中秋","f":"曲","c":["秋光海底，涌出银盘烂。","只怕微云淡河汉。","料姮娥应笑、醉舞仙人，今夜里，空恁樽前撩乱。","寻常三五夜，也有团圆，争柰人心未能满。","记当初破镜、飞上天时，双照影、留得人閒一半。","待仗他玉斧、再修成，问明月明年、共谁同看。"]},{"t":"洞仙歌 汴梁与许道真郭伯诚刘光甫同赋","f":"曲","c":["百年富贵，一觉邯郸梦。","识破中流退应勇。","纵生前身后、得个虚名，褒贬处。","一字由他南董。","故园归去好，还肯同归，大厦如今有梁栋。","对青天咫尺、列宿森然，君莫怪。","不见少微星动。","且拂袖、林泉作诗人，尽明月清风、笑人嘲弄。"]},{"t":"洞仙歌 谢杨成之寄梅","f":"曲","c":["陇头潇洒，辜负寻芳眼。","浪蕊浮花问名懒。","纵看看驿使、带得春来，祇恐怕，绿叶成阴子满。","暗香无恙否，月落参横，惆怅罗浮梦魂短。","赖故人情重、不减西湖，花上月、分我黄昏一半。","更选甚、南枝与北枝，是一种春风、待争寒煖。"]},{"t":"点绛唇 重阳菊间小酌同申元帅等","f":"曲","c":["秋树风高，可怜憔悴门前柳。","白衣去后。","闲却持杯手。","一笑相逢，落帽年时友。","君知否。","南山如旧。","人比黄花瘦。"]},{"t":"点绛唇 王怀州寿日戊戌十月一日","f":"曲","c":["横槊将军，是他马上男儿事。","河山表里。","养就英雄气。","衣锦归来，占尽人间贵。","功名遂。","神仙平地。","学取留侯计。"]},{"t":"点绛唇 冯巨川南斋牡丹","f":"曲","c":["花恨开迟，为花迟后为花恼。","问花开了。","却恨花开早。","人貌年年，不似花长好。","还知道。","年年人貌。","却笑花先老。"]},{"t":"点绛唇 酒赠车元帅","f":"曲","c":["著甚乾忙，人生只合糟丘老。","一杯软饱。","从事齐能到。","不读离骚，恐怕愁难埽。","春光好。","醉时便倒。","何处无芳草。"]},{"t":"点绛唇 锦堂寿日","f":"曲","c":["马上功名，射雕谁似将军手。","一朝肘后。","金印悬如斗。","锦绣山川，何似人长久。","闲中友。","为君添寿。","共劝忘怀酒。"]},{"t":"婆罗门引 重阳与元帅窦子温暨众友东城赏菊即席赋","f":"曲","c":["浮空霁色，江涵秋影雁初飞。","相逢共绕东篱。","点检樽前见在，人似晓星稀。","对满山红树，叶叶堪题。","大家露顶。","任短发、被风吹。","只恐黄花人貌，不似年时。","杯添野水，更何用、频频望白衣。","沉醉后、携手方归。"]},{"t":"清平乐 壬申岁六月十四日","f":"曲","c":["满斟绿醑。","劝我千金寿。","不住光阴催老丑。","三十七年回首。","镜中白发无多。","缺壶安用长歌。","有志封侯万里，列仙不柰臞何。"]},{"t":"清平乐 戏赠","f":"曲","c":["城南归路。","信马随车去。","家在白云楼下住。","帘幕深沉庭户。","不论天上人閒。","到头此债须还。","一枕行云梦觉，小楼却似巫山。"]},{"t":"清平乐 闰重九宋翔卿席","f":"曲","c":["黄花今后。","才是秋光暮。","依旧满城风又雨。","勾引锦囊诗句。","东篱尚可重游。","羡君来往风流。","莫惜樽前健倒，这回节去蜂愁。"]},{"t":"清平乐 锦堂寿","f":"曲","c":["青云得路。","休叹功名误。","好在辋川堪画处。","闻早抽身归去。","任他千丈风波。","光阴著酒消磨。","识破落花浮世，笑看金狄摩挲。"]},{"t":"谒金门 西斋得梅数枝色香可爱一日为泽倅崔仲明窃去感叹不己因赋谒金门十二章以写其怅望之怀 其一 寄梅","f":"曲","c":["开未彻。","先把一枝偷折。","看取黄昏今后别。","暗香浮动月。","谁为寻芳时节。","误了前村踏雪。","为问花閒能赋客。","如何心似铁。"]},{"t":"谒金门 其二 和邦直","f":"曲","c":["昏又晓。","蝶梦不栖芳草。","照映琼林人物好。","薰香荀令小。","不怕醉时健倒。","恐怕醒时花笑。","潘鬓都因愁白了。","老人心未老。"]},{"t":"谒金门 西斋得梅数枝色香可爱一日为泽倅崔仲明窃去感叹不己因赋谒金门十二章以写其怅望之怀 其十一 忆梅","f":"曲","c":["多少恨。","不见旧时风韵。","浪蕊浮花都懒问。","江头春有信。","誇甚寿阳妆镜。","说甚扬州诗兴。","云破月来堪弄影。","世閒无此景。"]},{"t":"谒金门 西斋得梅数枝色香可爱一日为泽倅崔仲明窃去感叹不己因赋谒金门十二章以写其怅望之怀 其四 叹梅","f":"曲","c":["频点检。","依旧雪肌清减。","似恨海东花使滥。","不教么凤探。","休笑诗人冷淡。","道尽影疏香暗。","桃杏虽然无藻鉴。","承当应不敢。"]},{"t":"谒金门 再和邦直","f":"曲","c":["人未晓。","古锦囊中诗草。","抹月批风滋味好。","气吞云梦小。","要把凤栖惊倒。","不学乌台嘲笑。","多少闲愁陶写了。","数篇吟可老。"]},{"t":"谒金门 西斋得梅数枝色香可爱一日为泽倅崔仲明窃去感叹不己因赋谒金门十二章以写其怅望之怀 其九 别梅","f":"曲","c":["怀抱恶。","犹被暗香著莫。","想在陇头谁领略。","一枝分付错。","今夜云窗雾阁。","明夜烟村水郭。","纸帐天寒人寂寞。","梦回闻雪落。"]},{"t":"谒金门 其一 和邦直","f":"曲","c":["烟雨晓。","梦断池塘春草。","坐上曲生风味好。","银杯休厌小。","刚要玉山醉倒。","社瓮酿成微笑。","人世闲愁都占了。","有情天也老。"]},{"t":"谒金门 河南府同知高诚之寿","f":"曲","c":["风渐力。","水剪飞花狼籍。","鼎沸笙歌催举白。","玉堂金马客。","欢动周人颂德。","唤起洛阳春色。","况值日南天道北。","老人星拱极。"]},{"t":"谒金门 西斋得梅数枝色香可爱一日为泽倅崔仲明窃去感叹不己因赋谒金门十二章以写其怅望之怀 其七 画梅","f":"曲","c":["偷造化。","秀出含章檐下。","为问花中谁可嫁。","海棠开已罢。","占了十分闲雅。","占了十分潇洒。","若使画工能此画。","九方皋相马。"]},{"t":"谒金门 西斋得梅数枝色香可爱一日为泽倅崔仲明窃去感叹不己因赋谒金门十二章以写其怅望之怀 其二 探梅","f":"曲","c":["谁便道。","昨夜雪中开了。","次第不将消息报。","探芳人草草。","宜在嫩寒清晓。","兴比孤山更好。","篱落逢花须醉倒。","惜花人易老。"]},{"t":"谒金门 西斋得梅数枝色香可爱一日为泽倅崔仲明窃去感叹不己因赋谒金门十二章以写其怅望之怀 其十 望梅","f":"曲","c":["春一半。","留与大家同看。","觅个温柔林下伴。","北枝犹未煖。","纵有姮娥照管。","可惜罗浮梦短。","断岭不能遮望眼。","几时魂却返。"]},{"t":"谒金门 西斋得梅数枝色香可爱一日为泽倅崔仲明窃去感叹不己因赋谒金门十二章以写其怅望之怀 其十二 梦梅","f":"曲","c":["随健步。","已过市桥江路。","费尽西湖多少句。","暗香留不住。","销得黄昏几度。","又是天寒日暮。","枕上吟魂无著处。","化为蝴蝶去。"]},{"t":"谒金门 西斋得梅数枝色香可爱一日为泽倅崔仲明窃去感叹不己因赋谒金门十二章以写其怅望之怀 其三 赋梅","f":"曲","c":["金的皪。","犹带枝头寒色。","休道北人浑未识。","自然梅有格。","初见花时摘索。","再见花时狼籍。","诗句眼前拈不出。","恼人楼上笛。"]},{"t":"谒金门 西斋得梅数枝色香可爱一日为泽倅崔仲明窃去感叹不己因赋谒金门十二章以写其怅望之怀 其六 赏梅","f":"曲","c":["全不让。","占了百花头上。","没个知音人共赏。","陶潜无处望。","也有江湖酒量。","也有风骚诗将。","休道花前无伎俩。","疏狂些子放。"]},{"t":"谒金门 西斋得梅数枝色香可爱一日为泽倅崔仲明窃去感叹不己因赋谒金门十二章以写其怅望之怀 其五 慰梅","f":"曲","c":["誇独秀。","动把春光泄漏。","谁道江南无所有。","一枝先入手。","须是日将月就。","那在风飘雨骤。","直待豆秸灰落后。","初尝山店酒。"]},{"t":"谒金门 赠教授李勉之","f":"曲","c":["初雨歇。","槐夏绿阴时节。","万里无云天绀滑。","一轮光皎洁。","好怕暂高还殁。","好怕暂圆还缺。","同是广寒宫里客。","相逢无话说。"]},{"t":"谒金门 西斋得梅数枝色香可爱一日为泽倅崔仲明窃去感叹不己因赋谒金门十二章以写其怅望之怀 其八 戴梅","f":"曲","c":["花谱内。","莫作等闲看待。","斗草吴王无可对。","有他西子在。","好在一枝竹外。","影也教人堪爱。","未免世閒儿女态。","折来头上戴。"]},{"t":"感皇恩 出京门有感","f":"曲","c":["忍泪出门来，杨花如雪。","惆怅天涯人离别。","碧云西畔，举目乱山重叠。","据鞍归去也，情悽切。","一日三秋，寸肠千结。","敢向青天问明月。","算应无恨，安用暂圆还缺。","愿人长似，月圆时节。"]},{"t":"感皇恩 李子搢寿日戊申年甲乙科第","f":"曲","c":["甲乙占科名，同根仙李。","富贵南柯梦相似。","天涯双桂，惭愧广寒宫里。","悤悤归去，觅佳山水。","休话升沉，休形愠喜。","且论南华养生理。","问君甲子，少我行年一纪。","须知乡党，礼莫如齿。"]},{"t":"感皇恩 杨成之生朝四月初三日","f":"曲","c":["啼鸟怨春归，一声声切。","蓂荚初生两三叶。","征鞍何处，撩乱杨花如雪。","鹊声头上，喜来时节。","香篆半销，寿波重酌。","玉带金鱼坐中客。","幕天席地，便是仙家日月。","试从今后，数蟠桃结。"]},{"t":"摸鱼儿 送侄谦甫出山","f":"曲","c":["这光景、能销几度，大都数十寒暑。","结庐人在山深处，万壑千岩风雨。","朝复暮。","甚不管、堂堂背我青春去。","高情自许。","似野鹤孤云，江鸥远水，此兴有谁阻。","功名事，休叹儒冠多误。","韩颠彭蹶无数。","一溪隔断桃源路，只有人家鸡黍。","歌且舞。","更不住、醉中时出烟霞语。","暂来樵斧。","贪看两争棋，人閒不道，俯仰成今古。"]},{"t":"满江红 和张文玘二首 其二","f":"曲","c":["名利场中，愁过了、几多昏晓。","试看取、江鸥远水，野麋丰草。","世事浮云翻覆尽，此生造物安排了。","但芒鞋竹杖任蹉跎，狂吟笑。","樽有酒，同谁倒。","花满径，无人埽。","念红尘来往，倦如飞鸟。","懒后天教闲处著，坐閒人比年时少。","向太行山下觅菟裘，吾将老。"]},{"t":"满江红 李孝先寿日四月八日","f":"曲","c":["小雨初晴，风摇荡、绿阴清昼。","见说道、长庚复向，人閒钟秀。","又对上番成竹笋，能忘赠别垂条柳。","看将来、三五月圆时，人如旧。","浮世事，君知否。","春梦断，空回首。","笑平生豪迈，气冲牛斗。","幽鸟自歌无谱曲，飞花故送长生酒。","待骑鲸、海上再相逢，为君寿。"]},{"t":"满江红 和张文玘二首 其一","f":"曲","c":["宿酒才醒，听唤起、一声春晓。","无限恨、满城风絮，一川烟草。","年少抛人容易去，万红千紫都开了。","试但教、头上插花枝，花应笑。","狂言在，人绝倒。","狂药尽，愁难埽。","待叮咛嘱付，再来青鸟。","团扇不堪题往事，断弦惟恨知音少。","但时时、频把镜来看，人将老。"]},{"t":"满江红 咏雪","f":"曲","c":["漠漠愁阴，银界晓、浩然一色。","谁剪水、就中撩乱，燕山如席。","天若有情天也老，高山底事头先白。","甚教人、错恨五更风，花狼藉。","寒欲退，刘叉笔。","深欲殁，韦郎膝。","问何如江上，孤舟蓑笠。","君不见、过门多恶客，等闲踏破琼瑶迹。","便粗豪、下马坐人床，寻欢伯。"]},{"t":"满江红 孟州长冯巨川诞日","f":"曲","c":["解愠风来，天气爽、绿阴庭院。","多少话、暂都分付，画梁双燕。","明月欲随人意满，十分未惬姮娥愿。","但一年、一度寿觞时，身长健。","玲珑曲，低低按。","玻璃盏，深深劝。","任春红，吹上桃花人面。","簪履尽居弹铗下，烟岚休恨平嵩远。","待试看、南极老人星，今朝见。"]},{"t":"瑞鹤仙 其二 弟李经略生朝","f":"曲","c":["绵绵仙种李。","有大道家风，逍遥活计。","长庚见苗裔。","问如何，谪在落花浮世。","曲生风味。","为唤回、席上和气。","被谁人说破，黄粱梦里，一场富贵。","何济。","不如归去，乐取闲身，登山临水。","众人皆醉。","笑独醒，泽畔憔悴。","但从今、管甚云翻雨覆，暂教心上无事。","且一杯、尽后一杯，满百千岁。"]},{"t":"瑞鹤仙 其一 弟李经略生朝","f":"曲","c":["晓窗寒气峭。","问小槽滴后，真珠多少。","博山寿烟袅。","向百花，头上梅花开了。","金樽频倒。","甚坐閒、犹恨杯小。","记去年今日，大家同庆，太平佳兆。","堪笑。","浮云世事，流水生涯，南柯梦觉。","风光正好。","欲退时，何似闻早。","把俗缘抛尽、逍遥林下，青松长伴难老。","与鹤鸣、立个家风，作千年调。"]},{"t":"瑞鹤仙 沁南守刘巨源诞节十月十五","f":"曲","c":["人生为郡乐。","推拯俗仁怀，济时英略。","和风散莲幕。","把功名一事，暂宜高阁。","兴来自酌。","要酒浇、胸次磊落。","比月中玉兔，别有长生，安心是药。","休错。","早还识破，一梦南柯，宦情渐薄。","北山素约。","试回首，千岩万壑。","况竹林、当日七贤游处，物外骖鸾驾鹤。","在烂柯、局畔樵人，看君下著。"]},{"t":"瑞鹤仙 细君寿日","f":"曲","c":["萧然林下秀。","笑檐外梅花，似人清瘦。","东风在垂柳。","算几时，吹散眉閒春皱。","兴来搔首。","问今朝、何处有酒。","怕一场醉后，渔歌樵唱，大家拍手。","知否。","眼前合计，无辱无荣，天长地久。","不须肘后。","望悬他，金印如斗。","待一朝、随我骑鲸去后，共寻天上王母。","把碧桃、花底流霞，为君添寿。"]},{"t":"瑞鹤仙 锦堂寿日壬寅十一月十五","f":"曲","c":["河东贤太守。","使草木生光，太行增秀。","功名落谁后。","醉归来，马上气冲牛斗。","一阳应候。","看春风、先到细柳。","笑座中有客，侯轻万户，诗誇千首。","依旧。","桂花盈处，蓂叶圆时，为君添寿。","满堂饮酒。","尽平生，倾盖素友。","对水云乡里、真山面目，钱家誇甚锦绣。","但年年、岁岁相逢，似人耐久。"]},{"t":"鹊桥仙 刘君祥寿癸卯二月十五日","f":"曲","c":["岁方值卯，斗方指卯，卯月月圆时候。","大家来把卯时杯，共与个、卯金为寿。","一杯寿酒，一杯贵酒，更有一杯富酒。","一杯留得贺添丁，见积善之家有后。"]},{"t":"鹊桥仙 段侯寿日","f":"曲","c":["题桥志气，沉碑勋业，不在著鞭人后。","浮云富贵转头空，似一梦、南柯太守。","辋川别墅，平泉小隐，此计地长天久。","金章还肯换蓑衣，买陂塘、旋栽杨柳。"]},{"t":"酹江月 壬午中秋与杨外郎仲朋侄婿郭仲进侄谦甫福昌待月","f":"曲","c":["中庭待月，正催诗雨过，暮山横碧。","别后连昌秋几度，一话团圞今夕。","万里清风，坐中为我，埽尽云踪迹。","冷光不似，寻常些小窥隙。","应笑白发功名，倚楼看镜，惟酒禁愁得。","且斗樽前身见在，亹亹风生谈席。","洛下仙舟，斗间星使，邂逅非生客。","天涯双桂，广寒谁念幽寂。"]},{"t":"酹江月 六月十四日感旧先生诞日","f":"曲","c":["臞仙风格，暂天教作个，人閒浮客。","白发光阴催老境，谁见摩挲铜狄。","挥剑成河，曳戈却日，著尽回天力。","黄粱梦觉，转头一段陈迹。","休问花谢花开，春兰秋菊，总被风欺得。","华表鹤来人换世，惟有眼前山色。","偎径栽松，傍门插柳，笑比陶彭泽。","晚凉月下，一樽聊永今夕。"]},{"t":"酹江月 王怀州寿日丁酉年","f":"曲","c":["堂堂玉立，看坐间挥麈，风生谈席。","相对竹林三四友，气压兰亭豪逸。","招隐诗中，登楼赋内，此恨无人识。","缺壶歌后，佩刀还向谁得。","何用三窟谋身，醉乡一笑，与元规尘隔。","好在辋川堪画处，写出高人椽笔。","云外舄凫，月边笙鹤，邂逅骑鲸白。","蟠桃会上，不为王母生客。"]},{"t":"酹江月 承济之和复用元韵","f":"曲","c":["脱巾挂壁，向雀罗门外，几回迎客。","纵有一樽陶写后，不遇当年仪狄。","未著祖鞭，先投班笔，老恨无才力。","天涯地角，断蓬流落踪迹。","归去作个闲人，锦囊诗句，都向闲中得。","谩说他乡光景好，多少世情风色。","损友违三，益朋近五，易卦占山泽。","人閒星聚，不知天上何夕。"]},{"t":"鹧鸪天 其二 和天久雨","f":"曲","c":["丧乱来来少睡眠。","□□□榻又留连。","那堪又下潇潇雨，可奈无秋薄薄田。","□□□，□残年。","眼前戈戟尚森然。","得他真个风云手，不信人间有漏天。"]},{"t":"鹧鸪天 吊李克修","f":"曲","c":["须信人生足别离。","此情惟有落花知。","方忧跃马明年事，忽至黄杨厄闰期。","生有限，去何疑。","骑鲸公子赋成时。","得从上界真官府，百计招魂不肯归。"]},{"t":"鹧鸪天 其一 和天久雨","f":"七言绝句","c":["滴滴寒声搅夜眠。","行云似与楚山连。","百川到底终归海，一水元来不护田。","□□□，□□□。","□□□□□□□。","□□□□□□□，□□□□□□□。"]},{"t":"萧权府三害图","f":"曲","c":["长桥之蛟，南山之虎。","在彼州曲，父老所苦。","岂独若此，亦有周处。","周乃慨然，耻闻斯语。","薄险投深，踊跃健武。","尔蛟既除，尔虎既去。","周乃自励，履规蹈矩。","卒以将种，效忠典午。","按剑平西，贞节克举。","瑕以瑜掩，过以功补。","身虽云亡，名播千古。"]},{"t":"止姚亚之刲羊","f":"曲","c":["养生之鞭，陇种之苗。","欲鲁去朔，在齐闻韶。","咄嗟老饕，腹如瓠枵。","踏破菜园，合吃藤条。"]},{"t":"焦天禄野叟听音图","f":"曲","c":["梨园弟子，天宝之后。","谁其知音，百岁遗叟。","曲终怅然，泪迸林薮。","时清眼明，万事缄口。"]},{"t":"唐叔王韦生卧虎图","f":"曲","c":["梁鸯之养，或失其时。","曹公之肉，不救其饥。","羊质而皮，狐假而威。","谁能于此，辩是与非。"]},{"t":"学中史正之会客","f":"曲","c":["有怀伊人，在泮饮酒。","我客戾止，其尝旨否。","未见君子，我心孔疚。","惠然肯来，小大稽首。"]},{"t":"烟江绝岛图","f":"曲","c":["江风不波，峭壁森立。","冥冥飞鸿，翔而后集。"]},{"t":"双松古渡图","f":"曲","c":["倾盖相逢，堂堂两公。","寂寥渡口，以济不通。"]},{"t":"古柏寒泉图","f":"曲","c":["冬夏长青，昼夜不舍。","拔本塞源，岂知量者。"]},{"t":"纸扇","f":"曲","c":["竹疏而骨，楮剥而肤。","权以行巽，风乎坐隅。"]},{"t":"棕扇","f":"曲","c":["直节贯中，怒发冲上。","朝蝇暮蚊，畏风长往。"]},{"t":"成之夜谈省庭新事","f":"五言古诗","c":["伟哉青云器，底蕴莫能见。","开口论利害，坐客服雄辩。","汪汪江海量，气不许黄宪。","从来布衣愿，一掷轻百万。","投瓜必报琼，岂望在焚券。","虽承雨露恩，慷慨辄自献。","与其便于已，孰若于国便。","盖尝推此心，天下欲兼善。","儒家惟有孟，日夜讲不倦。","傥以利为利，请看货殖传。"]},{"t":"复和","f":"五言古诗","c":["驱驰戎马閒，太平不复见。","往往谈隽永，宁许齐士辩。","有田宜早归，夺恐遭窦宪。","再三欲买邻，愧我无千万。","难倩沽酒奴，待立便了券。","筹堂天下士，风度迈羲献。","别后曳裾人，造门恨无便。","握手再相逢，虚左待益善。","平生身口累，老大折腰倦。","莫讶陶先生，自作五柳传。"]},{"t":"镇山堂","f":"五言律诗","c":["峥嵘屋下城，突兀城上屋。","初看颇惊眼，再见堪捧腹。","能无鬼神笑，可柰疮痍俗。","不哀梁閒叟，欲竭南山木。"]},{"t":"嵇康淬剑石","f":"五言古诗","c":["寻常论养生，未得养生说。","拟从林下游，一书交尽绝。","既无当世志，安用三尺铁。","频频石上磨，神光浸秋月。","可怜粗疏甚，自谋何太拙。","危弦发哀弹，幽愤终莫泄。","死留身后名，有愧侍中血。"]},{"t":"樊哙戏石","f":"五言古诗","c":["丈夫气慷慨，隐迹在东市。","或逢逐鹿人，乃弃屠狗事。","壮哉鼓刀勇，旁若舞剑地。","遂摧拔山力，自叹时不利。","至今空山石，传是将军戏。","能兴卯金运，颇与黄石类。","不期两都后，复有三国志。","过客对春风，徒洒山阳泪。"]},{"t":"寄筹堂","f":"五言古诗","c":["老为人所怜，贫恨友独寡。","等闲门外车，尽入宰肉社。","欲随射虎将，争柰无匹马。","安得化为云，四方逐东野。","大庇天下士，拟作万閒厦。","顾我盖头茅，宁肯助一把。","非无问舍心，或恐卧床下。","纵有愿留人，有馆不能假。","还因索居久，往往罪商也。","须待舍馆定，然后见长者。"]},{"t":"毛晋卿肖山堂","f":"五言古诗","c":["悠然林下客，世事颇能料。","闲中意自适，身外名肯钓。","卜居山之阳，初为识者笑。","势将陵岱华，气欲吞嵩少。","方寻愿谷归，稍近孙台啸。","微茫数烟岫，巉绝对云峤。","为我增双明，未必在远眺。","始虽如直友，久乃得心照。","恐随有力去，或被移文诮。","己见成膏肓，百计莫可疗。","一时烟霞语，慎勿骇廊庙。","咄哉肖山堂，所以警不肖。"]},{"t":"庙学落成","f":"楚辞体","c":["斯文天末器，吾道有时厄。","方嗟凤兮衰，遽叹麟也获。","继遭秦焚书，又被鲁坏宅。","迩来天下事，多自马上得。","不修下车礼，不献在泮馘。","不授羽林经，不讲博士席。","旁若没字碑，肯见一逢掖。","偶因长乐老，尽挟兔园册。","及见中选人，始知为学益。","学者如牛毛，自古数濩泽。","连年取青紫，易于地芥拾。","争将逸驾攀，遂向塞路辟。","挥之无倚门，从者皆入室。","肃肃俎豆风，洋洋弦歌邑。","几时复论秀，四海望偃伯。","术能向者谁，世无秋风客。"]},{"t":"德老栽花成竹","f":"五言律诗","c":["物性随所移，岁晚气自变。","失却本来身，还于身外见。","寻参玉版禅，如对菩萨面。","丛林一花祖，派入香严传。"]},{"t":"刘汉臣堂甫北归","f":"五言律诗","c":["哀哉同队鱼，尽在枯池里。","纵免鼎中烹，将见渴欲死。","造物何不仁，岂独困二子。","我虽江湖心，恨无斗升水。"]},{"t":"母应之饷黍","f":"曲","c":["忆昔周室衰，周人咏黍离。","君今饷我黍，为赋黍离诗。","厥初蓺黍时，饭牛使牛肥。","八月黍未穫，胡儿驱牛归。","胡儿不满欲，我民还买犊。","今秋犊未大，又被胡儿逐。","胡儿皆饱肉，我民食不足。","食不足，尚可鬻子输官粟。"]},{"t":"游碧落","f":"五言古诗","c":["浮云翳炎景，长夏惬幽事。","相陪林下友，共造金碧地。","清流漱寒玉，老树耸苍翠。","何人开山祖，妙处发天秘。","悠悠岁月深，剥落磨崖字。","遨头兴不浅，有酒留客醉。","幽鸟背人飞，不惯闻鼓吹。","抵暮出山门，溪风送归骑。"]},{"t":"史遂良索诗","f":"五言古诗","c":["立身有道邦，谁似直哉史。","流传百世后，各各异行止。","许史有何厚，在汉势如彼。","安史有何薄，在唐乱如此。","人之贤与愚，皆为类所使。","近从侪辈中，偶得一狂士。","未能通一经，谓可拾青紫。","时时出俚句，技痒不自己。","只恐落调歌，难入知音耳。","纵横言世事，不顾剌舌耻。","焉知阮嗣宗，口不挂臧否。","年高鬓如雪，乡曲所不齿。","试与阿戎谈，咄哉犁之子。"]},{"t":"留别李巽之","f":"五言古诗","c":["嗟嗟平生交，所恨不耐久。","几年戎马间，太半正丘首。","忆初识君面，同门皆小友。","倏忽五十春，相见成老叟。","淹淹泉下人，树拱骨已朽。","崎岖见在身，何幸得此寿。","感慨岁云晚，哀泪迸林薮。","古今均一梦，万事付杯酒。"]},{"t":"司谏许道真徵复图","f":"曲","c":["君不见退休绿野平淮相，灵台不许丹青状。","又不见五湖归去鸱夷桨，越人争铸黄金像。","功成身退天之道，道直天怜去官早。","盐梅须借筑岩人，羽翼重来采芝老。","袖中谏草力回天，害除利兴车载悬。","何忧不识荆州面，图画如今处处传。"]},{"t":"郭显道美人图","f":"曲","c":["君不见昭阳殿里蓬莱人，终惹渔阳胡马尘。","又不见吴宫夜夜乌栖曲，竟使姑苏走麋鹿。","移人大抵物之尤，丧乱未免天公愁。","虽然丹青不解语，冷眼指作乡温柔。","试问人閒何处有，画师恐是倾国手。","却怜当日毛延寿，故写巫山女粗丑。"]},{"t":"宣差射虎","f":"七言古诗","c":["北原风劲霜草枯，草閒出没藏于菟。","眈眈来此被谁驱，不防邂逅冯妇车。","将军胆气勇有馀，手中笑撚金仆姑。","等闲如射兔与狐，两眼错莫精光无。","深山大泽失所居，或撩汝头编汝须。","可怜肉食无远图，伎俩不及黔之驴。"]},{"t":"群鼠为耗而猫不捕","f":"曲","c":["欺人鼠辈争出头，夜行如市昼不休。","渴时欲竭满河饮，饥后共觅太仓偷。","有时凭社窃所贵，亦为忌器不忍投。","某氏终贻子神祸，祐甫恨不猫职修。","受畜于人要除害，祭有八蜡礼颇优。","近怜衔蝉在我侧，何故肉食无远谋。","眈眈雄相猛于虎，不肯捕捉分人忧。","纵令同乳不同气，一旦反目恩为雠。","君不见唐家拔宅鸡犬上升去，彼鼠独堕天不收。"]},{"t":"埽晴妇","f":"七言古诗","c":["卷袖褰裳手持帚，挂向阴空便摇手。","前推后却不辞劳，欲动不动谁掣肘。","偶人相对木与土，神女但誇朝复暮。","龙公不作本分事，中閒多少闲云雨。","见说周人忧旱母，宁知东海无冤妇。","慇勤更倩封家姨，一时断送龙回首。"]},{"t":"雨雹","f":"七言古诗","c":["云龙失守元气乖，隐隐愁听狂车雷。","须臾飘骤不成雨，一天风雹从何来。","交横散落星石陨，纷霍迸击冰山摧。","坳平忽讶坑谷满，垤起俄作丘陵堆。","惊忙飞走残夭夭，斲器枝叶枯根荄。","穿窗入户弹相射，填街溢巷把莫推。","恢恢难补天网漏，凛凛欲压坤轴颓。","一方生理遭殄瘁，造物不恤空自哀。","是时仲夏行冬令，谁把四序颠倒催。","虽有舜弦愠不解，孰谓邹律春能回。","阳虽位降乾道在，一阴才进力可排。","履霜之渐此其始，司寒挟党结祸胎。","春秋大小百馀国，独向鲁地三为灾。","世间万事岂不见，那用区区书观台。","我思天变岂徒尔，以象告人当自裁。"]},{"t":"鼎斋","f":"曲","c":["茂陵千载文园客，流传耳孙犹病渴。","引饮自嫌江海窄，家无曲藭柰腹疾。","水帝之魂成水厄，女丁妇壬不相得。","始图一溉滋汤旱，卒见九河归禹画。","尝闻秋夫曾疗鬼，大胜扁鹊能起虢。","君不见上医可医国，异哉鼎斋堪鼎食。"]},{"t":"姚子昂画马","f":"七言律诗","c":["雄姿卓立开天骨，腾踏万里如神速。","可怜不遇九方皋，空使时人指为鹿。","自从大奴守天育，无由更骋追风足。","中原一战收乾坤，白发将军髀生肉。"]},{"t":"苴履","f":"七言古诗","c":["待诏门前东郭趾，蓝关路上仙人迹。","雪花纷披盖地白，东家不借借不得。","虽然近市屦亦无，以故为新即有馀。","同行留我木上座，铺过仰渠金十奴。","一生能著屐几两，用心犹在阮孚上。","不须更觅下邳侯，山林此计成长往。"]},{"t":"儿辈剡木作匙","f":"七言律诗","c":["一震之威乃如此，坐閒或失将军匕。","不能便染公子指，有意欲割昆奴耳。","小儿造物穷物理，斗柄之揭如其尾。","虽然剑头有炊米，有愁遇著捩手鬼。"]},{"t":"闻蔡州破","f":"曲","c":["不周力摧天柱折，阴山怨彻青冢骨。","方将一掷赌乾坤，谁谓四面无日月。","石马汗滴昭陵血，铜人泪泣秋风客。","君不见周家美化八百年，遗恨黍离诗一篇。"]},{"t":"筹堂寻梅","f":"七言律诗","c":["萧疏篱落谁家圃，寻芳信逐游蜂去。","眼前荆棘少人行，马蹄直到香来处。","怕愁贪睡独开迟，瘦损春寒鹤膝枝。","可是东君苦留客，斜风细雨不堪诗。"]},{"t":"和秦彦容韵 其一","f":"曲","c":["养贤列鼎手自烹，燮调元化和如羹。","马蹄一蹙燕地裂，毡裘尚拂阴山雪。","将军表请愿出师，壮士挥戈惟恐迟。","武成才试二三策，黍离已见闵周诗。","纵横门外豺狼路，我老此身无著处。","君不见平淮十万兵，犹向襄阳守朱序。"]},{"t":"和秦彦容韵 其二","f":"曲","c":["君不见子幼自劳羔日烹，何如命驾季鹰吴中煮莼羹。","又不见姜侯设鲙凿冰裂，何如徒步拾遗长镵黄独雪。","幸遇南来董鍊师，说似壶天日月迟。","谪仙之游乃非谪，长安市上斗酒百篇诗。","蒲轮休指商山路，得到白云采芝处。","诸生待揖隆准翁，马上未遑事庠序。"]},{"t":"和秦彦容韵 其三","f":"曲","c":["猎犬已为兔死烹，犹向汉俎分杯羹。","脚靴手板冻欲裂，尚立唐阶没膝雪。","三寸舌为帝者师，终比赤松见事迟。","相看一笑在目击，何用左思招隐诗。","出门便是天坛路，云閒指点巢仙处。","不辞杖屦从子游，王者之后养老在西序。"]},{"t":"和秦彦容韵 其四","f":"七言古诗","c":["谷因辟后厌鼎烹，那在丘嫂轑釜羹。","冠未挂前已先裂，一簪却上山头雪。","我虽无师心我师，速修何恨下手迟。","论中自得养生理，笔底尽是游仙诗。","休向回车问前路，终须有个安排处。","晴窗点检白云篇，不知谁为作者序。"]},{"t":"和秦彦容韵 其五","f":"曲","c":["不嫌瓠叶日犹烹，不羡公子染指争鼋羹。","不把荷衣等闲裂，不羡曹人共服麻如雪。","爱身肯似贱场师，凡骨只愁轻举迟。","北山未出移休勒，东老虽贫乐有诗。","望中云海蓬莱路，谁道乐天无归处。","一千年鹤再来时，行雁难将弟兄序。"]},{"t":"暴雨","f":"曲","c":["疾雷破山云暗天，雨脚不断如麻悬。","淋浪一室无乾处，何异露坐乘漏船。","鼠牙便是溃堤蚁，墙有百道飞来泉。","狂客岂因狂药使，眼花如落井底眠。","采石江头弄明月，一夕去作骑鲸仙。","我虽忘我亦可怜，但恐不免蛟龙涎。","苦无根源笑潢潦，可能朝宗东注觅海道。","君不见耒阳禹力所不到，至今难寻杜陵老。"]},{"t":"綵楼","f":"七言古诗","c":["层层华构高且崇，万綵纠结填青红。","何人下手夺天巧，都入意匠经营中。","书契以来未省见，异事惊倒百岁翁。","郢斤般斧莫敢近，却立屏息惭无功。","寒窗戛戛鸣机妇，积年杼柚一日空。","山川谓可锦绣裹，尘土尽皆罗绮封。","前者攀辕后者挽，奔车径欲趋灵宫。","三年送迎礼虽旧，人事不与天时同。","方当炎属行夏令，权势大抵归祝融。","神之与人无厚薄，盖以至诚能感通。","豚蹄豆酒道傍祝，所获神赐亦已丰。","闾阎疾苦还知否，我为大夫歌大东。"]},{"t":"上九里谷与济之君祥仲宽李德方朱寿之姚子昂","f":"七言古诗","c":["太行巍巍形势尊，造物设险雄中原。","巨灵一朝擘石裂，连峰忽断开山门。","侵云直上几千尺，挂壁一径愁攀援。","十步回头五步坐，慄慄汗出如浆翻。","清风掖至最高顶，下视寰海尘埃昏。","天坛咫尺若有待，顾我不往惭食言。","世间好处岂不爱，脚力虽尽心常存。","为君试写远游兴，夜半月出清吟魂。"]},{"t":"剥莲蓬","f":"七言律诗","c":["相将去采秋江莲，青房戢戢实且圆。","倒靫收菂亦可喜，春笋未剥空流涎。","玉井有花开十丈，至今依旧藕如船。","试索绿茎不寻藕，与谁共此从巢仙。"]},{"t":"辽漆水郡王降虎","f":"曲","c":["秋风渐高秋草衰，空山校猎千骑围。","突然有物势□猛，万里侯相食肉肥。","横行妥尾不畏逐，挟□似有百步威。","当时扈从懦于鼠，虽欲下车人其非。","将军一奋跃身出，气雄志勇捷若飞。","攘臂搏虎虎负去，须臾□皮擒虎归。","北方锐儿皆好武，无愧疋马及短衣。","声名赫赫耀前古，却笑冯妇胆力微。","胙田命氏报恩异，至今漆水生光辉。","君不见射石李广一箭亦可喜，死不封侯知者希。"]},{"t":"遗善堂","f":"曲","c":["君不见遗子韦侯只一经，相门出相那在金满籯。","又不见燕山教子以义方，灵椿老去五枝丹桂芳。","破散钱堆一百屋，紫微不愿有子如窟郎。","陷为天下轻薄子，伏波不愿有子学季良。","身前身后事茫茫，我恤我躬犹未遑。","长把贤愚挂怀抱，请看积善之家遗善堂。"]},{"t":"赠出家张翔卿","f":"曲","c":["大袖斜襟粗布袍，髻丫撑似弥明高。","滑稽自谓世可玩，清净不守形徒劳。","百年光景已强半，容易便把青春抛。","欲向蓬壶寻福地，柰何龙伯钓后负山无海鳌。","欲驾天风朝帝阙，柰何巫阳去后九虎守关牢。","养生未获一溉力，那忍遽绝平生交。","但令造物哀正直，岂肯屈曲从仙巢。","留侯学道欲轻举，尚且强食扶金刀。","安期当年本策士，意气直谒扛鼎豪。","平地作仙亦不恶，或恐上界官府名难逃。","君不见醉吟居士不归海上山，又不见昌黎先生屈曲自世閒。","况非出尘风骨羽化难，夜叉白日守天关。","黄庭正恐坐误读，铁锁纵垂那可攀。","我笑学仙王屋著道冠，只待河南李侯脱去然后还。"]},{"t":"筹堂燕","f":"楚辞体","c":["阴阴池馆落花泥，出入通家独见知。","曾遭江上淘河嚇，又被巢边野雀欺。","且欺且嚇亦不恶，柰有鼠辈窥其儿。","儿方在卵卵何危，哀鸣若诉奚胜悲。","主人能得腹中事，百计护持彼毒无所施。","羽毛养就刀剪齐，雄雌相随引雏飞。","寻常百姓家，汝巢非汝宜。","春兮来，秋兮归，莫忘乌衣巷里时。"]},{"t":"赵倅司马山谢雨","f":"七言古诗","c":["去岁不雨民忧深，愆阳亢甚多伏阴。","冥冥造物岂难料，感以至诚神所歆。","我公默祷若响应，出岫谁谓云无心。","天瓢疑是池中水，三日以往皆为霖。","淋漓元气满人望，解愠何止薰风琴。","家家豚酒乐丰岁，空山鼎沸箫鼓音。","春祈秋报有常典，仰荷灵贶如桑林。"]},{"t":"四舍人生日","f":"曲","c":["骥之子，凤之雏，精彩丰容美且都。","年至十二三，头角己异同队鱼。","积善之家庆有馀，掌中幸得双明珠。","定知他日必充闾，不妨更读古人书。","绛帐先生当今之范模，步亦步，趋亦趋，执经北面预先讲唐虞。","明主何尝不用儒，相门出相文可无。","岂独手撚金仆姑，能骑生马驹，然后称为大丈夫。"]},{"t":"赠儒医卜养正","f":"七言律诗","c":["孰亲如身在所慎，一病能恼安乐性。","囊中探丸起九死，以其病病人不病。","岂独和扁号神圣，能于鬼手夺人命。","尝闻上医可医国，何不使权造物柄。"]},{"t":"游济源","f":"七言古诗","c":["元戎小队闲登临，悠悠旌旆穿山林。","太行南下路险涩，不惮著脚穷幽寻。","清源祭秩世所重，乔木掩映灵宫深。","是时方口雨初过，天风破晓开微阴。","入门为问庙见礼，白发黄冠通古今。","且言享诚非享物，那在与俗占浮沉。","鞠躬执简默有祷，脯酒纵薄神所歆。","几年愿违莫能遂，至此始得偿初心。","点检图经叹禹迹，山青水绿无知音。","竹根醉倒客星散，夜听波底蛟龙吟。"]},{"t":"樊氏昆仲懒窠","f":"曲","c":["君不见读书边，孝先谓。","师可嘲，何典记。","又不见梁州阴子春，足不肯洗恐败事。","何须向人说道理，养得疏慵性如此。","摆手便行谁家子，嵩洛之间两居士。","未尝点检形骸外，挂角羚羊心已死。","问之非渔亦非樵，人言似痴还似高。","叔夜自知不堪七，以书遂绝平生交。","一官从此束高阁，赖是天教闲处著。","时人争赋懒窠诗，我羡懒窠诗不作。"]},{"t":"壬申岁旱官为设食以济饥民","f":"曲","c":["千里地赤泽未沾，骄阳为沴烈火炎。","就中秦头晋尾旱魃所栖托，十室九室突不黔。","撑肠一饱岂易得，咀嚼草木如荠甜。","山川课云职不举，无乃风伯号令严。","民是天民天自恤，何时霹雳起龙潜。"]},{"t":"男扬洗儿","f":"七言律诗","c":["自惭无德为儿父，今朝把酒为儿寿。","为儿今赋洗儿诗，愿儿他日于儿厚。","我犹不恤况我后，委蜕自天汝非有。","速宜修德大吾门，无复心童年十九。"]},{"t":"儿归来","f":"曲","c":["儿归来，儿归来，百年郎罢恨，何日宁馨回。","东去但除严母墓，望思空筑茂陵台。","儿归来，儿归来，一声未尽一声哀。"]},{"t":"赠郭显道医","f":"曲","c":["恶石聚散元气朴，本草搜剔造化窟。","俱收并蓄笼中物，山精水怪藏不得。","休言魄为天所夺，入其手者命可活。","须防姮娥去奔月，大胜扁鹊能起虢。","君不见钱子飞，药不敢施为鬼胁。"]},{"t":"和荅董用之","f":"楚辞体","c":["将军死战血染衣，空山白骨鬼夜啼。","洗兵政要及时雨，天祸未悔无云霓。","卧龙不起主张汉，猎犬待烹侥倖齐。","就中儒冠身多误，如坐矮屋头常低。","敢将龙钟哀造物，但幸老大能扶犁。","咄哉董生三寸舌，善谑不思为虐兮。","人间回首忧患始，去之不速将噬脐。"]},{"t":"再和秦彦容韵","f":"曲","c":["扊扅歌后伏雌烹，箸犹未下愁覆羹。","布衾多年踏里裂，夜半寒窗洒风雪。","待与重寻痛饮师，东山杲杲日出迟。","撑肠拄腹文字五千卷，一字不入高人诗。","几年不踏红尘路，直入白云最深处。","君不见洛阳城下来归魂，一梦思乡叹温序。"]},{"t":"荅祁定之韵","f":"五言律诗","c":["黄菊催秋暮，青山劝客归。","事随时渐改，人与物皆非。","爽气收残暑，闲云送落晖。","平生会心似，别后往来稀。"]},{"t":"游太平泉","f":"五言律诗","c":["稍有林泉兴，相陪杖屦游。","百年人易老，千种事堪愁。","是处花无主，谁家酒可篘。","芳时好行乐，春去不能留。"]},{"t":"宿夹谷彦实庵","f":"五言律诗","c":["挂名仙籍上，晦迹茂林閒。","门外丹河水，墙头明月山。","境随心自远，人与话俱闲。","应笑红尘客，区区谩往还。"]},{"t":"河桥成 其一","f":"五言律诗","c":["预积他山木，重新两岸堤。","龙依天上卧，虹傍水心低。","不假鞭秦石，何劳立蜀犀。","落成应有日，谁向柱先题。"]},{"t":"河桥成 其二","f":"五言律诗","c":["河广思同济，天寒怕涉冬。","冰虽将自合，船尚不宜从。","柱引来归鹤，渊藏未跃龙。","一编圮上叟，千载愿相逢。"]},{"t":"河桥成 其三","f":"五言律诗","c":["势截长河浪，横陈百步梁。","经营方断手，过涉不褰裳。","漫惜千金瓠，休誇一苇航。","西风箫鼓咽，奠酒水仙堂。"]},{"t":"癸巳冬至 其一","f":"五言律诗","c":["共愁天纪乱，依旧日南时。","气本自然应，策今谁可推。","每怀添线女，还意覆杯儿。","偃蹇无归计，天涯两鬓丝。"]},{"t":"癸巳冬至 其二","f":"五言律诗","c":["岁以四时成，气自一阳始。","虽然废羲职，那可乱轩纪。","人生几寒暑，天道频甲子。","徒嗟潦倒身，汲汲百年里。"]},{"t":"乙未冬至","f":"五言律诗","c":["已应黄宫律，初生复卦阳。","道随天在北，愁与日俱长。","节物惊时换，年光有底忙。","浮云多变态，试与问何祥。"]},{"t":"任仲山弄璋","f":"五言律诗","c":["奕世多阴德，传家得宁馨。","人閒熊有梦，天上昴无星。","喜洽犀钱座，光生玉树庭。","钟情笑卢老，白发望添丁。"]},{"t":"五哥生日","f":"五言律诗","c":["落落青云器，天然骨骼奇。","自从怀橘后，每恨学书迟。","同乐怜荆树，相煎笑豆萁。","气豪常自许，跃马是男儿。"]},{"t":"代四哥赠","f":"五言律诗","c":["相戒南陔养，长看花萼辉。","义深姜季被，恩重老莱衣。","队似鱼同戏，行如雁共飞。","读书当自勉，继取锦堂归。"]},{"t":"元夜有感","f":"五言律诗","c":["春城行欲遍，百感到愁边。","市冷犹灯火，人稀尚管弦。","梅从今夜落，柑忆旧时传。","归去西窗月，无情照不眠。"]},{"t":"四哥生日","f":"五言律诗","c":["秀出三株树，芳联五桂枝。","杜家怜骥子，徐氏重麟儿。","已有高门望，方当志学时。","一杯添寿酒，满酌不须辞。"]},{"t":"寒食","f":"五言律诗","c":["为恋风光好，那堪节物催。","事随浮世往，花似去年开。","莫洒无家泪，须倾有限杯。","诗人多少兴，都向醉中来。"]},{"t":"九日下山","f":"五言律诗","c":["宰肉陈平社，折腰元亮乡。","车无门外辙，菊与径皆荒。","所恨国难守，若为家不忘。","天威寒气逼，急急下山阳。"]},{"t":"王生寿日","f":"五言律诗","c":["几度县弧节，当年琢玉郎。","徐行知礼让，幼学爱文章。","莫厌鱼同队，休随燕入堂。","眉间色多喜，禁脔近东床。"]},{"t":"游青莲 其一","f":"五言律诗","c":["闲携方外友，同谒梵王宫。","山吐三更月，松摇万壑风。","流年飞鸟过，浮世落花空。","不有归来兴，何能见远公。"]},{"t":"游青莲 其二","f":"五言律诗","c":["行处春风恶，山中胜槩藏。","渐佳如蔗尾，薄险似羊肠。","翠揖双峰角，清临一水堂。","夜长僧睡少，为我话兴亡。"]},{"t":"过云中","f":"五言律诗","c":["把酒不成醉，出门行路难。","客愁千里破，归梦五更残。","三仕有何喜，一生常鲜欢。","恨无南去雁，为我报平安。"]},{"t":"宿海会寺 其一","f":"五言律诗","c":["佛堂光未放，桑下唤难回。","是处皆堪歇，何山不可开。","泉因龙吐出，经自兔衔来。","径向黄沙过，寻僧问劫灰。"]},{"t":"宿海会寺 其二","f":"五言律诗","c":["青山云水窟，杖锡几时来。","竹待香严击，松经道者栽。","西江无水吸，震旦忽花开。","三笑图中友，同倾破戒杯。"]},{"t":"游碧落","f":"五言律诗","c":["寂历松閒寺，临流胜槩藏。","断云开石壁，横吹爽溪堂。","谩与诗情在，留连道话长。","行人贪吊古，归路半斜阳。"]},{"t":"九里谷","f":"五言律诗","c":["九曲羊肠路，千层剑戟山。","行钩藤蔓刺，坐印石花斑。","树发三春暮，云归万壑闲。","相陪林下屐，虽倦不知还。"]},{"t":"食芡","f":"五言律诗","c":["池底休铺锦，鸡头自有栽。","柔中皆水性，刚外乃天才。","精彩惟鱼目，珠圆出蚌胎。","坐间咄嗟致，不似荔枝来。"]},{"t":"颖阳元道人虚白庵","f":"五言律诗","c":["有山心可算，有水耳堪洗。","飘飘元逸人，寓意在山水。","勘破人閒世，不听心与耳。","一室虚生白，自得吉祥止。"]},{"t":"八日登山同谒吴王祠","f":"五言律诗","c":["老树凋残尽，灵祠寂历中。","古今时易改，幽显意能通。","岁享屡登乐，俗追三让风。","送迎人散后，日落乱山空。"]},{"t":"阳城怀旧 其一","f":"五言律诗","c":["路梗伤时事，春归感物华。","风波千万丈，烟火两三家。","树杪失巢燕，墙根无主花。","当年人不见，何处是生涯。"]},{"t":"阳城怀旧 其二","f":"五言律诗","c":["道途行处恶，故旧别来稀。","涧口分流水，林梢挂落晖。","好山留客住，幽鸟背人飞。","门外秋光老，征鞍尚不归。"]},{"t":"上长平寄杨成之","f":"五言律诗","c":["衰迟长在外，矍铄愧征鞍。","世路惊心恶，天风刮面寒。","迢迢人渐远，冉冉岁将残。","今夜梅稍月，同谁共倚栏。"]},{"t":"独坐","f":"五言律诗","c":["地偏无俗客，日在掩柴扉。","暑退闲蒲扇，凉生换葛衣。","风高云散影，露下月扬辉。","独据胡床坐，心清即道机。"]},{"t":"乙亥过河","f":"五言律诗","c":["一身长道路，四海尚风尘。","昔作依刘客，今为去鲁人。","渡河年在亥，乞酒岁非申。","别后山中友，相逢话又新。"]},{"t":"河阳呈苗简叔","f":"五言律诗","c":["妖氛长斗北，杀气尚河东。","人物不如古，地图祗自雄。","三城环野水，二麦卧天风。","多少逃亡屋，荒凉晚照中。"]},{"t":"即事","f":"五言律诗","c":["炎凉愁里过，陵谷暗中迁。","素拙生生计，寻耕下下田。","为嫌频告籴，却恨不逢年。","门外催租吏，长妨对圣贤。"]},{"t":"中秋对月","f":"五言律诗","c":["云山怀素隐，秋兴暂来归。","月与人同醉，星随客渐稀。","入河蟾不没，绕树鹊何依。","浩气凝光界，瑶台梦欲飞。"]},{"t":"山中寄张汉臣李广之","f":"五言律诗","c":["枳棘非所栖，系匏焉不食。","未黔墨子突，又夺伯氏邑。","一年三褫服，半岁两涂敕。","归去来山中，无器亦无得。"]},{"t":"经童","f":"五言律诗","c":["盈门修郑校，同队执韦经。","苏子应千里，徐儿向九龄。","雁行成次序，莺语太丁宁。","堪笑西城老，朝朝酷教刑。"]},{"t":"自遣","f":"五言律诗","c":["居闲聊自适，造物果何如。","生理年年拙，交情日日疏。","吠犹闻蹠犬，技可笑黔驴。","谁识徘徊意，西山有旧庐。"]},{"t":"过星轺","f":"五言律诗","c":["古道开天险，危峰拔地形。","连营南北戍，过客短长亭。","野烧惊山鬼，胡云掩将星。","何人弄羌管，哀怨不堪听。"]},{"t":"小旱云而不雨","f":"七言律诗","c":["阿香谁使送雷声，敢望天瓢一滴分。","恨魃长为周地虐，闵尪几被鲁人焚。","风吹海立垂垂雨，泽与山通处处云。","何事卧龙犹不起，得微往见葛陂君。"]},{"t":"复用韵","f":"七言律诗","c":["区区布谷不停声，安得银河水半分。","汤稼未应枯后溉，周川岂独旱如焚。","是谁主当知时雨，有底商量出岫云。","造物不为天下计，只将花事了东君。"]},{"t":"十六日雨","f":"七言律诗","c":["平地俄惊霹雳声，老龙功过此应分。","不知东海因谁祭，却笑西华欲自焚。","四面蔽亏无日月，百神奔走会风云。","时人那识天公事，一溉惟知有巨君。"]},{"t":"王子荣过家上冢","f":"七言律诗","c":["暂令元戎小队行，尽驱春色入山城。","葱葱佳气随轩盖，袅袅高风卷旆旌。","题柱桥边男子志，散金闾里故人情。","贵游前后知多少，不使堂虚昼锦名。"]},{"t":"用赵之美留别韵 其一","f":"七言律诗","c":["把酒离筵且莫辞，坐中瓜葛暂相依。","花从识后常含笑，鸟自还时想倦飞。","往事微茫春梦断，故人牢落晓星稀。","天涯白发禁愁得，好在西山不早归。"]},{"t":"用赵之美留别韵 其二","f":"七言律诗","c":["长短亭中送别时，问君东去复何依。","今宵明月三人共，来日红尘一骑飞。","倾盖莫嫌相见晚，断弦惟恨赏音稀。","天涯尽道还家好，笑我虽归似不归。"]},{"t":"用赵之美留别韵 其三","f":"七言律诗","c":["为君不惜送行诗，但恨蒹葭失所依。","流水尽朝东海去，孤云只向太行飞。","仕途冰炭收心早，客路参商见面稀。","一曲阳关歌未彻，声声头上听催归。"]},{"t":"用赵之美留别韵 其四","f":"七言律诗","c":["遥指东山去恨迟，争如莲幕早来依。","须知宋鹢犹能退，有底齐禽尚不飞。","洛下书生怜我少，燕南壮士似君稀。","主人好客恹恹醉，正要髡留肯放归。"]},{"t":"用赵之美留别韵 其五","f":"七言律诗","c":["平生藏器待何时，除却荆州不可依。","预报行人应鹊噪，相将送客有花飞。","雁从去后弟兄少，莺未来时朋友稀。","不尽赤心今日话，东山无以我公归。"]},{"t":"赴山阳","f":"七言律诗","c":["立马西风不忍行，往回只是片时程。","一年又作半年客，百里有如千里情。","落日寒林山下路，淡烟疏竹水边城。","愿君把酒休惆怅，四海由来皆弟兄。"]},{"t":"白文举王百一索句送行","f":"七言律诗","c":["世事纷纷乱似麻，不堪愁里度年华。","伤心城郭来家鹤，过眼光阴赴壑蛇。","弹铗歌中成老境，班荆话后各天涯。","何时造物归真宰，却睹人间第一花。"]},{"t":"承二公宠和复用元韵 其一","f":"七言律诗","c":["脱却朝衫著纻麻，残年犹复梦京华。","世情共指鹿为马，天意反教龙作蛇。","白发不公人易老，青山有素恨无涯。","那禁送别东郊外，满目离离溅泪花。"]},{"t":"承二公宠和复用元韵 其二","f":"七言律诗","c":["有客衡从说蓺麻，要教身后见西华。","若为养得能言鸭，未解除他引睡蛇。","归去稍知闲气味，荒唐犹种老生涯。","眼前浮世凭谁问，独倚东风看落花。"]},{"t":"重午偶题","f":"七言律诗","c":["龙钟叹我百年身，几见山城节物新。","水荇长如牵翠带，石榴半似蹙红巾。","可怜今日依刘客，便是当时吊屈人。","谁道南来风解愠，试从比屋问吾民。"]},{"t":"春日","f":"七言律诗","c":["白头不柰隙驹催，惯饮屠酥醉后杯。","百岁无多偏昼短，一年将尽又春来。","东君得地权终在，北斗随天柄已回。","造物却还真宰手，众人今后试登台。"]},{"t":"和参谋李舜举 其一","f":"七言律诗","c":["平步青云感遇初，试看倾盖气何如。","橘皮应笑陈人榜，隽永争谈辩士书。","梦鹿果能谁得鹿，知鱼未必子非鱼。","青山马上多诗句，北斗以南名不虚。"]},{"t":"和参谋李舜举 其二","f":"七言律诗","c":["一怒王师吊伐初，堂堂人物古谁如。","剑头何患无炊米，楯鼻多应有檄书。","尽道公孙能跃马，应怜学士独焚鱼。","旌旗未度长河水，千骑元戎已捣虚。"]},{"t":"和东庵孔安道韵 其一","f":"七言律诗","c":["拟结闲中一草堂，此心安处即吾乡。","须知见在身为患，见说长生药有方。","老去看书徒引睡，愁来得句不成章。","从前习气都除尽，待与高人论坐忘。"]},{"t":"和东庵孔安道韵 其二","f":"七言律诗","c":["淡泊生涯共一堂，杖藜踏遍水云乡。","不妨庐结在人境，应念客来从远方。","三笑可无陶靖节，八仙宜得贺知章。","袖中时出烟霞语，习气师兄亦未忘。"]},{"t":"和子荣","f":"七言律诗","c":["暂使彭宣到后堂，安昌只以醉为乡。","浮云世事日千变，流水生涯天一方。","老子兴虽如庾亮，故人恩不减苏章。","能消几两寻山屐，回首狐丘本未忘。"]},{"t":"五舍人生朝","f":"七言律诗","c":["积德高门庆有馀，隔年记得掌中珠。","清新月窟两枝桂，俊逸渥洼千里驹。","戏自老成看蜡凤，志从小异见樗蒲。","一朝腾踏青云上，快睹徐卿第二雏。"]},{"t":"筹堂寿日 其一 王乔","f":"七言律诗","c":["此生但觉醉乡宽，谁谓螭犹北海蟠。","处处相迎皆倒屣，人人共喜欲弹冠。","州应向日悬刀梦，山试今朝拄笏看。","仙驭未来缑氏鹤，月明吹彻玉笙寒。"]},{"t":"筹堂寿日 其二 王霸","f":"七言律诗","c":["乌衣历历是名家，人物于今比晋多。","俗论不侵挥麈话，壮怀都付缺壶歌。","虽无金埒堪调马，赖有黄庭可换鹅。","见说长江欲飞渡，那须冰合望滹沱。"]},{"t":"和子搢中秋","f":"七言律诗","c":["最后宾来举白浮，要须同赏桂华秋。","蛾郎应恨灯无焰，娈女能教月再修。","分外高寒天上阙，就中明彻水边楼。","姮娥不我为生客，休把光芒取次收。"]},{"t":"和子搢九日谩兴 其一","f":"七言律诗","c":["此身到处贾胡留，细雨斜风冷淡秋。","佳节又从愁里过，故乡不似旧时游。","试拈红叶题诗句，强摘黄花泛酒瓯。","落帽龙山几人在，云沉鸟没恨悠悠。"]},{"t":"和子搢九日谩兴 其二","f":"七言律诗","c":["节物催人分外愁，干戈眼底未能休。","丹枫落处吴江冷，黄菊开时灞岸秋。","可是凉风添寂寞，更堪缺月照绸缪。","悠悠今古何须问，泪洒牛山亦过忧。"]},{"t":"沁园怀古","f":"七言律诗","c":["风波平地难开眼，剑戟群山欲割肠。","冠盖随时成物故，园林何日破天荒。","摩挲碑石空怀古，点检图经为补亡。","谁是熙熙堂上客，近来老子也和光。"]},{"t":"和即事","f":"七言律诗","c":["拟将唾手取封侯，世事那禁种种愁。","未可搏他冯妇虎，终须享此景升牛。","但知勿剪甘棠在，莫为难图蔓草忧。","自古贵人天所予，定教名字到金瓯。"]},{"t":"和新秋","f":"七言律诗","c":["帘捲西山雨乍停，自知时节候虫声。","新凉邂逅如佳客，残暑留连似宿酲。","可见韩檠灯下志，且怜班扇箧中情。","若为解得吾民愠，更鼓南风一再行。"]},{"t":"寄史正之","f":"七言律诗","c":["往来门下亦风流，分得筹堂几许忧。","刚甚养他横槊马，何如了取济川舟。","人还忌器休投鼠，谁为蹊田欲夺牛。","闻早抽身闲处著，不妨仍带醉乡侯。"]},{"t":"闻捷音招王德华吴天章等出山","f":"七言律诗","c":["红尘一骑报平安，知是元戎小队还。","且喜好音来汴水，仍将旧事问潼关。","横云自护车箱涧，落日空衔箭筈山。","只恐膏肓归不得，早随春色到人閒。"]},{"t":"用子荣河桥送别韵","f":"七言律诗","c":["河桥把酒不成欢，正是离人去住閒。","公道几时饶白发，世情今日见青山。","娟娟明月无家对，惨惨孤云待我还。","惭愧慇勤花里鸟，一声声送出阳关。"]},{"t":"承徐子贤贾仲常张伯英宠和复用韵","f":"七言律诗","c":["天涯杯酒强追欢，白发光阴转首閒。","独夜梦魂千里月，暮年心事数重山。","回肠都为愁将断，行脚犹疑债未还。","傥得一廛休老地，柴门今后定牢关。"]},{"t":"宿村舍 其一","f":"七言律诗","c":["别后曾无一日欢，风光都在落花閒。","眼青羞对门前柳，头白相惊雪里山。","华表鹤来犹是客，乌衣燕去不知还。","森森庭院荒荆棘，虎豹窥人夜撼关。"]},{"t":"宿村舍 其二","f":"七言律诗","c":["握手亲情有底欢，疏篱茅舍两三间。","尚怜作者千年调，那肯分人一半山。","安得意如张翰适，凭谁放取浩然还。","得君斗酒须防客，不怕重门更著关。"]},{"t":"宿村舍 其三","f":"七言律诗","c":["怀抱何曾得少欢，春愁飞上两眉间。","一瓢谩酌独清水，几屐能穷无尽山。","见说酒兵长日备，未知诗债几时还。","须防别后将军禦，不待寻盟辄斩关。"]},{"t":"宿村舍 其四","f":"七言律诗","c":["三两残杯不尽欢，强陪年少贵游閒。","客中未必常为客，山上那堪复有山。","鹤发都从愁里变，貂裘直待醉时还。","一朝却入庞公市，惊倒城门老抱关。"]},{"t":"闵董用之","f":"七言律诗","c":["怪底年来懒下帷，似嫌榜尾姓名题。","一枝自谓乌难借，百里谁知凤肯栖。","颇讶生前徒强项，未应老后不然脐。","试将点检平时友，太半佳城在马蹄。"]},{"t":"用之次韵复荅","f":"七言律诗","c":["小斋飘雨注风帷，门外青山困品题。","足蹑尽知齐是假，胆尝争柰越犹栖。","任教别后书盈箧，嬴得年来气暖脐。","聊与老农歌帝力，一缸村酒荐豚蹄。"]},{"t":"夜雨 其一","f":"七言律诗","c":["元气淋漓彻九垓，那消掩耳一声雷。","雨虽不解知时节，云岂无心出岫来。","所恨龙潜犹未起，大都天意卒难回。","等闲莫话为霖事，且对檐花尽此杯。"]},{"t":"夜雨 其二","f":"七言律诗","c":["夜半天公号令催，即时惊起阿香雷。","须知稼穑艰难甚，谁把阴阳燮理来。","不使魃为周地虐，定应龙自葛陂回。","邻家酒熟留连客，聊与愁人共一杯。"]},{"t":"夜雨 其三","f":"七言律诗","c":["化工宁许著诗催，平地俄惊失箸雷。","行雨梦从巫峡断，为霖人自傅岩来。","老农学稼无多力，太史书年有几回。","爱酒陶家才种秫，何如共此即时杯。"]},{"t":"用之请还公府用韵拒之","f":"七言律诗","c":["□寇将军力自宣，幕中议论可回天。","气吞骄虏鞭先著，威定并门檄罢传。","正恐一隅防饮酒，休从百尺笑求田。","杨雄禄位谁能动，姑为侯巴草太玄。"]},{"t":"吊刘伯祥","f":"七言律诗","c":["记曾林下见臞仙，惆怅红尘未断缘。","不惮广文寒处坐，屡逢元亮醉时眠。","难逃辰巳贤人岁，有负齑盐太学年。","落落天才无地用，却还英气与山川。"]},{"t":"伊阙鸂鶒堂 其一","f":"七言律诗","c":["千年古道入荒城，破屋颓垣一聚尘。","天地如何收险阻，山川犹觉露精神。","馀波禹贡朝宗水，习俗周南既醉人。","把酒西风无限兴，黄花时节对嘉宾。"]},{"t":"伊阙鸂鶒堂 其二","f":"七言律诗","c":["一日滩流浅自分，滩头鸂鶒似通神。","大都鸾棘无多地，毕竟乌台得几人。","浮世堂堂春易去，随时局局事皆新。","当年灵翼今何在，满目西风动白蘋。"]},{"t":"乱后寄兄 其一","f":"七言律诗","c":["长剑何人倚太行，毡裘入市似驱羊。","怒降白起不仁赵，死守裴侯无负唐。","可柰昆炎焚玉石，更堪蜀险化豺狼。","紫荆犹是阶前树，风雨何时复对床。"]},{"t":"乱后寄兄 其二","f":"七言律诗","c":["万井中原半犬羊，纵横大剑与长枪。","昼烽夜火岂虚日，左触右蛮皆战场。","丁鹤未归辽已冢，杜鹃犹在蜀堪王。","此生不识连昌乐，目送孤鸿空断肠。"]},{"t":"送赵庆之赴邠州","f":"七言律诗","c":["且莫悤悤数去程，一壶别酒为君倾。","三年簿领妨行乐，十里溪山管送迎。","湓浦芦花风里恨，渭城柳色雨中情。","三峰无复同州看，休著新诗笑不平。"]},{"t":"别合阳申伯福昆仲","f":"七言律诗","c":["百里相望邂逅迟，如今始得话心期。","情深堂上留髡夜，兴尽山阴防戴时。","客舍故人那用送，异乡游子不胜悲。","烟村水驿秦川路，来往邮筒好寄诗。"]},{"t":"和子搢来韵","f":"七言律诗","c":["新年桃李似无情，回首繁华一梦惊。","点检青毡非故物，等闲倾盖昧平生。","雨中燕子还留客，风里杨花欲送行。","试听东流桥下水，向人时作断肠声。"]},{"t":"郭仲山寿日","f":"七言律诗","c":["乘兴游山也自贤，千金奚羡筑台燕。","谁为洛下同舟友，人道江头弄月仙。","欲向漳源归旧隐，便从莞谷种闲田。","橐驼树得长生理，不解如君养性天。"]},{"t":"和河上修桥 其一","f":"七言律诗","c":["故里风光衣锦游，赋诗谁与共临流。","相逢依旧山青眼，也有何愁浪白头。","官渡方当横槊日，合肥正是著鞭秋。","坐閒有客誇雄辩，不念题桥志未酬。"]},{"t":"和河上修桥 其二","f":"七言律诗","c":["日日相陪杖屦游，往来林下亦风流。","云閒隐隐堆螺髻，雨后鳞鳞涨鸭头。","休恨临津经始晚，且看利涉落成秋。","寻常公事闲中了，诗债如何尚不酬。"]},{"t":"和河上修桥 其三","f":"七言律诗","c":["眼底关山忆旧游，滔滔河汉自东流。","星槎不觉来天上，铁锁那能护石头。","顾我已嫌题柱晚，喜君正是济川秋。","酒閒豪气谁堪共，一醉千金价不酬。"]},{"t":"和河上修桥 其四","f":"七言律诗","c":["落魄天涯颇倦游，片帆归去得安流。","几年无事誇犀首，一旦封侯看虎头。","飞将正当南渡日，拾遗还是北征秋。","龙钟不称凌烟像，只有山林志可酬。"]},{"t":"壬寅九日同史正之刘济之君祥仲宽姚子昂东城小酌寄锦堂王君玉 其一","f":"七言律诗","c":["长天一色雁行斜，雨过南山气势加。","懒后不冠羞白发，兴来无酒负黄花。","何人见忆闲陶令，有客徒嘲老孟嘉。","秋景满前宜共赏，未应件件属诗家。"]},{"t":"壬寅九日同史正之刘济之君祥仲宽姚子昂东城小酌寄锦堂王君玉 其二","f":"七言律诗","c":["兴来落笔任横斜，坐上朋樽续续加。","貌似叶红皆被酒，头如雪白也簪花。","金风渐急秋将暮，玉树相依客尽嘉。","酩酊入城扶不去，临街下马是谁家。"]},{"t":"随州长官张鹏举暨","f":"七言律诗","c":["寂寥秋思梗吟怀，几度柴门鹊噪开。","一话胜看江表传，百书不及陇头梅。","马催行色日边去，雁送归程天际来。","万里龙庭莫辞远，中原事业望人才。"]},{"t":"和子荣悼恒山韵 其一","f":"七言律诗","c":["功名人比汉淮阴，猛虎俄因犬辈擒。","星落旄头兵似火，云屯细柳士如林。","岂期虞虢乖唇齿，谩倚良平作腹心。","洒尽英雄忧国泪，变风那得不伤今。"]},{"t":"和子荣悼恒山韵 其二","f":"七言律诗","c":["消尽群阳道长阴，将军何患敌难擒。","唐家外望归藩镇，汉室中兴仰羽林。","忽堕曹吴分鼎计，方知胡越济舟心。","依然锦绣山川在，一旦浮云变古今。"]},{"t":"刚忠公","f":"七言律诗","c":["未除妖气斗牛閒，一夜长星落将坛。","天意欲将全节畀，人心无柰此时寒。","断头那肯降朱泚，血指谁思灭贺兰。","立尽太行山上石，我公忠烈不容刊。"]},{"t":"同济之游百家岩怀郭延年右感","f":"七言律诗","c":["雨晴闲向百岩游，今古都成一段愁。","老衲解回山下虎，真人跨入洞中牛。","水流花落三春暮，鸟没云沉万事休。","有道碑前空堕泪，往来谁复共仙舟。"]},{"t":"辛丑中秋夜与用亨汉臣济之君祥子昂仲宽及诸同志聚饮于学宫阴不见月 其一","f":"七言律诗","c":["节物相催近觉频，胜游携酒意何勤。","几人白发对明月，万里青天愁片云。","袅袅风高秋已半，厌厌客醉夜将分。","督邮气味从来恶，今日尊前也献芹。"]},{"t":"辛丑中秋夜与用亨汉臣济之君祥子昂仲宽及诸同志聚饮于学宫阴不见月 其二","f":"七言律诗","c":["莫嫌胜日燕游频，且慰寒窗力学勤。","白也停杯将问月，退之利剑欲开云。","清光难比秋三夜，痛饮何辞酒百分。","况在頖宫思乐地，与君共采水中芹。"]},{"t":"送别曹汉卿","f":"七言律诗","c":["马上功名柰老何，出门无地不风波。","凭谁试著回天力，有客空挥却日戈。","青眼乍惊行处少，赤心常笑话中多。","愁人近亦无肠断，又听离筵送别歌。"]},{"t":"九日济之君祥仲宽子昂携酒于汉臣书斋小酌已而乘兴与众老人会于城西马氏东篱谈笑尽醉扺暮而归为赋此以纪一时之胜事","f":"七言律诗","c":["相扶醉袖出西城，翠展秋山一望晴。","坐上孟嘉嘲未解，篱边陶令话多情。","酒犹强饮狂时药，菊莫寻餐落后英。","兴尽归来天色暮，老人星散月还生。"]},{"t":"暮春和端甫韵","f":"七言律诗","c":["雨夕风朝乐事妨，老来犹自为花忙。","春光一岁只三月，尊酒百年能几场。","辛苦衙蜂输蜜课，等闲巢燕得泥香。","如何复共遨头醉，待把银瓶指点尝。"]},{"t":"承和复用韵","f":"七言律诗","c":["草草杯盘兴不妨，一年一度送春忙。","我无酒量难投社，君有诗情合擅场。","衣锦堂前冠盖贵，落花径里绮罗香。","暂时忘却愁滋味，蓦上心来似胆尝。"]},{"t":"答赵之美见和","f":"七言律诗","c":["不堪春事等闲妨，汲汲光阴过隙忙。","青眼久悬高士榻，白头羞入少年场。","风从定后花犹落，月自修来桂复香。","休向兵厨问消息，且教下马客先尝。"]},{"t":"李子搢约同上山督之","f":"七言律诗","c":["踏青时节醉何妨，一掬归心想见忙。","杖屦不须从捷径，觥筹且莫恋欢场。","明山秀水家家景，野草闲花处处香。","休讶登临无脚力，世閒险阻备曾尝。"]},{"t":"答史正之","f":"七言律诗","c":["草堂深处百无妨，却为高岑对属忙。","啼鸟送春归阆苑，妖星乱世局文场。","闲花空怨绿衣使，煮酒不随青杏香。","见说曲生风味少，尚堪留与老饕尝。"]},{"t":"阳城题北台观壁","f":"七言律诗","c":["几年空负北山移，今日方知见事迟。","犹忆王凫初去后，忽惊丁鹤暂来时。","虽无壁上题名字，颇愧棠阴听讼诗。","指似荒城旧游处，西风摇落菊花期。"]},{"t":"客中寒食","f":"七言律诗","c":["断蓬踪迹寄天涯，剑戟林中阅岁华。","又值禁烟焦举节，柰无对月少陵家。","惊心咄咄催归鸟，触目冥冥溅泪花。","老后愁怀谁遣得，未应端的酒胜茶。"]},{"t":"和徐子贤西行留别","f":"七言律诗","c":["便从倾盖话诗情，风雨端能落笔惊。","金马谩誇三学士，碧油曾见一书生。","竹溪花圃留连醉，水郭烟村取次行。","自恨年来怀抱恶，与君相别但吞声。"]},{"t":"调祁定之","f":"七言律诗","c":["风埃满面发蓬垂，欲学乔松久远期。","浮世几场漂杵血，流年一局烂柯棋。","不须玉女引巢父，那在神官邀退之。","果待吹嘘送天上，人閒事了未为迟。"]},{"t":"侄谦甫巩县寄鱼","f":"七言律诗","c":["掣三牵两得沈腥，顾我庖厨远未能。","几度敲针无处钓，一朝醒酒不须冰。","居官止合如羊续，命驾何须学季鹰。","当念家风本寒素，莫从今后爇馋灯。"]},{"t":"母师圣醉中落水用郭进之韵","f":"七言律诗","c":["无人桥上醉婆娑，脚力危时可柰何。","贺监未应真落井，屈平到底也随波。","浮云世事黄粮梦，斜日秋风薤露歌。","点检交情能有几，柴门今后雀堪罗。"]},{"t":"下鳌背","f":"七言律诗","c":["浮云踪迹去留难，谷谤岩嘲勒我还。","毕竟一身无著处，大都百计不如闲。","无多伎俩三休外，是亦风流二老閒。","昨日主人今日客，回头山色若为颜。"]},{"t":"许司谏归来图","f":"七言律诗","c":["社稷忧深志未舒，陆浑山下赋闲居。","几年不复朝鸡梦，一旦翻随垄鹤书。","□□朱游徒折槛，宠踰疏□□悬车。","商岩了却和羹事，方信旁求象不虚。"]},{"t":"寄伊阳令周文之括户","f":"七言律诗","c":["几年客里厌驰驱，故向伊川好处居。","刚受一廛同许子，谁知四壁过相如。","厥田不称中中赋，此事真堪咄咄书。","疲俗脂膏今已尽，看看鞭算及舟车。"]},{"t":"和子搢秋晚出郭","f":"七言律诗","c":["陶写诗人得句忙，旧游能复忆嵩阳。","山头云霁雨声歇，水面风来花信香。","今日事虽非向日，故乡景自胜他乡。","杖藜忘却寻归路，独立河桥咏晚凉。"]},{"t":"和述怀 其一","f":"七言律诗","c":["簪履三千气压齐，寒林那羡一枝栖。","坐中有客鵩将赋，门外何人凤欲题。","沽酒未尝防恶犬，著鞭宁复待荒鸡。","夕阳休凭栏干望，今日长安不在西。"]},{"t":"和述怀 其二","f":"七言律诗","c":["拟将齐物物难齐，惟有山林迹可栖。","身望凤池惭不到，名登雁塔愧先题。","未能忘旧归家鹤，长是思鸣失旦鸡。","天为东周道垂丧，肯生夫子在关西。"]},{"t":"戏嘲","f":"七言律诗","c":["江西社里几诗流，咏月嘲风未肯休。","得句不能当竞病，措辞那敢向春秋。","笑翻王氏三珠树，惊倒张家五凤楼。","带系雪诗三十韵，胜如骑鹤上扬州。"]},{"t":"答子荣","f":"七言律诗","c":["行藏事拙且乘流，游遍人閒老即休。","多汗愈肤三伏暑，渐衰潘鬓一时秋。","风高势欲欺茅屋，雨急声疑在竹楼。","今世宦情何处好，但忧无蟹有监州。"]},{"t":"送史邦直入洛","f":"七言律诗","c":["肉山南去汗如流，了取公家事便休。","征棹不沾瓜蔓水，归装莫待菊花秋。","忙中暂过平嵩阁，别后频登望省楼。","若问鹤鸣近消息，翅翎飞不到扬州。"]},{"t":"即事","f":"七言律诗","c":["铁马长驱汗血流，眼前戈甲几时休。","谁能宰似陈平社，那免悲如宋玉秋。","漠漠微凉风里殿，萧萧残夜水边楼。","千村万落荒荆棘，何止山东二百州。"]},{"t":"宽张文玘","f":"七言律诗","c":["怪来久不造龙门，依旧相逢一笑温。","任把锦囊嘲李贺，休将布鼓诧王尊。","事随势过心犹骇，言与时违舌可吞。","谁为书生肯推毂，绨袍且念故人恩。"]},{"t":"和窦君瑞","f":"七言律诗","c":["勒石燕山后世名，子孙蝉蜕起风尘。","谁怜喜鹊飞来意，自叹灵椿老大身。","愁见灌夫杯酒过，梦惊苏蕙锦书新。","几年客里无情话，一笑相逢姓麦人。"]},{"t":"窦子温宅为有力者所夺","f":"七言律诗","c":["谩劳买宅著千万，此又卜居何□从。","得把茅来头可盖，但教窗下膝能容。","尚怜相贺巢边燕，知为谁甜花底蜂。","速向元龙问闲舍，暂将一榻过今冬。"]},{"t":"子荣途中见忆有先生在世人中龙三十年前到月宫之句依韵谢答","f":"七言律诗","c":["高楼日日望元龙，禾黍离离闵故宫。","两地谩看千里月，五湖能借半帆风。","囊锥颖脱何难出，名纸毛生未肯通。","好在沁阳山色里，一廛宁许寄杨雄。"]},{"t":"吊曹庆之","f":"七言律诗","c":["杯酒中间气沓拖，从教千丈起风波。","丝棼世事无一可，花落人生得几何。","休向棘林长夜哭，试听蒿里送行歌。","岂容身后钟君在，阿骛如今嫁者多。"]},{"t":"吊王德华","f":"七言律诗","c":["衰鬓愁添镜里丝，流年恰及梦中蓍。","可怜白日佳城地，正值黄杨厄闰时。","抚柩恨深元伯母，负薪情惨叔敖儿。","髑髅不识生前乐，枉却招魂费楚辞。"]},{"t":"赠医郭显道","f":"七言律诗","c":["小隐嵩阳种德时，智能博物物皆归。","笼中无愧狄仁杰，山下常逢台孝威。","子细论来生可养，斩新卦得遁之肥。","粗疏谁似嵇中散，幽愤诗成忆采薇。"]},{"t":"焦彦昭失中子","f":"七言律诗","c":["相逢地下果何如，自谓情钟亦太愚。","未必珠能空老蚌，岂期玄不与童乌。","且怜商也无三罪，尚喜徐卿有二雏。","万事尽归天予夺，速宜收泪谢玄夫。"]},{"t":"读五代史","f":"七言律诗","c":["破却千金筑一台，折冲阃外望人才。","中原山岳河分断，塞上牛羊草引来。","西海正惊天狗堕，北人忽拥帝羓回。","犹怜仙掌英灵在，能把潼关闭不开。"]},{"t":"春温轩","f":"七言律诗","c":["三尺枯桐膝上横，一弹洗尽绮罗尘。","芙蓉城里谁为主，姑射山前别有人。","云雨不侵行处梦，丹青难写醉时真。","早寻林下乘鸾侣，莫遣春温过却春。"]},{"t":"索和长平诸诗友送行韵信笔奉呈君玉闰之资客中一笑 其一","f":"七言律诗","c":["汉厦非无论道毡，自惭老去鬓皤然。","闲愁似海藏皮里，往事如风过耳边。","几度班荆谁与话，一朝倾盖□相怜。","柴门近日多来客，火速移床待孝先。"]},{"t":"索和长平诸诗友送行韵信笔奉呈君玉闰之资客中一笑 其二","f":"七言律诗","c":["青春人物正当时，咫尺云天快乐披。","相见便如胶漆密，此行还似筈弦离。","方传细柳将军令，或赋甘棠召伯诗。","待得一朝公事了，联镳西去未为迟。"]},{"t":"索和长平诸诗友送行韵信笔奉呈君玉闰之资客中一笑 其三","f":"七言律诗","c":["此身莫辄犯针毡，只合浮沉委自然。","久堕风波人海里，暂依云汉使星边。","斗升乞活真堪笑，青紫归耕亦可怜。","早晚皇家重名器，著鞭当在祖生先。"]},{"t":"索和长平诸诗友送行韵信笔奉呈君玉闰之资客中一笑 其四","f":"七言律诗","c":["老觉粗疏过往时，赤心今始为君披。","交情大抵无新旧，人事从来有合离。","见说片辞能折狱，未尝一话不言诗。","河东自古文明地，可惜儒冠感遇迟。"]},{"t":"昨晚蒙降临无以为待早赴院谢闻己长往何行之速也因去人寄达少慰客中未伸之志耳 其一","f":"七言律诗","c":["纵横人市尽裘毡，一旦衣冠气索然。","岂信鲁连归海上，颇哀屈子老江边。","汗流石马谁堪恨，草没铜驼世所怜。","莫惮区区困刀笔，论功终让指踪先。"]},{"t":"昨晚蒙降临无以为待早赴院谢闻己长往何行之速也因去人寄达少慰客中未伸之志耳 其二","f":"七言律诗","c":["书生掉舌岂其时，手底青编亦倦披。","铁锁尚沈江漠漠，铜驼又没草离离。","阴山路上明妃曲，天宝年中杜甫诗。","古往今来几兴废，白头恨见太平迟。"]},{"t":"任仲山谈西府事","f":"七言律诗","c":["德音到处下情通，喜动山城百岁翁。","和气挽回中国化，威声振起外台风。","少酬汉使澄清志，不愧周官燮理功。","南北封疆归一统，太平立法自河东。"]},{"t":"唐臣满月洗儿索诗故赋","f":"七言律诗","c":["幽径疏篱竹外村，淡烟斜日水边城。","地形占斗辨南北，风俗以人分重轻。","坐上有山围似画，樽中得酒论如兵。","青春将种多才调，拂袖林泉恐不情。"]},{"t":"唐臣满月洗儿索诗故赋","f":"七言律诗","c":["白头休恨梦熊迟，却是人閒久远期。","有客已为摩顶记，为君复草弄璋诗。","一从老蚌生珠后，再值姮娥月满时。","咫尺昂霄看英物，不须女子作门楣。"]},{"t":"送郡侯段正卿北行 其一","f":"七言律诗","c":["征途万里朔风寒，过尽阴山复有山。","岁既在于辰巳后，星多客向斗牛间。","漫漫积雪无冬夏，劫劫飞鸿自往还。","若到龙庭试回首，太行一片白云闲。"]},{"t":"送郡侯段正卿北行 其二","f":"七言律诗","c":["猎猎霜风堕指寒，一鞭行色抵天山。","马嘶衰草孤烟外，雁没长空落照间。","入塞尽穿毡帐过，去乡须待锦衣还。","功名大抵黄粱梦，薄有田园便好闲。"]},{"t":"送参谋刘君祥 其一","f":"七言律诗","c":["寂历书斋独坐寒，白头羞见雪中山。","虚名得失蜗争外，浮世荣枯蚁梦閒。","半夜朔风催客起，几时新月望君还。","鹤鸣林下无人共，何处烟霞不可闲。"]},{"t":"送参谋刘君祥 其二","f":"七言律诗","c":["马首风花拂面寒，十年两度过阴山。","浮云暮暮朝朝里，行雁兄兄弟弟閒。","大抵故乡生处乐，莫教明主放时还。","如今造物尤难料，枉使身心不得闲。"]},{"t":"杜门","f":"七言律诗","c":["近来人事颇相乖，独坐何曾得好怀。","犬吠为连沽酒市，鸡鸣长傍读书斋。","门终待学张家塞，闼恐难当哙等排。","恶客就中多气岸，时时下马系堂阶。"]},{"t":"中秋 其一","f":"七言律诗","c":["露下天街一气凉，月明不复被云妨。","正当金帝行秋令，疑是银河洗夜光。","鲛室影寒珠有泪，蟾宫风散桂飘香。","席间醉客忙归去，独共三人尽此觞。"]},{"t":"中秋 其二","f":"七言律诗","c":["共对青天好举觞，从前三五是寻常。","一年佳节秋将半，万里清辉夜未央。","才向缺时舒窈窕，欲从盈后敛光芒。","姮娥曾得长生药，我欲停杯问此方。"]},{"t":"和乔舜臣韵 其一","f":"七言律诗","c":["画图悬个老人星，一炷香烟祷处灵。","见说蟠桃将结子，不知槁木已忘形。","倚空山色青排闼，埽地槐阴绿满庭。","凡骨恨无轻举便，且求强健保残龄。"]},{"t":"和乔舜臣韵 其二","f":"七言律诗","c":["几年鬓发已垂星，岂是长生药不灵。","席上精神欢伯力，尘中面目偶人形。","来归徒讶荒陶径，学退还思过鲤庭。","郑重世情相爱甚，一杯酒劝望延龄。"]},{"t":"郎子云酒熟同李茂卿史正之豪取不许","f":"七言律诗","c":["爱钱措大眼孔小，病酒先生舌本乾。","债是寻常谁不有，囊嫌羞涩且留看。","三人未必一人损，豪气难忘习气酸。","毦氉相逢欲空去，从来如此四并难。"]},{"t":"再赴阳城用前韵别茂卿子云正之","f":"七言律诗","c":["谁使腰间印欲悬，不知面上唾才乾。","先生敢以督邮去，坐客莫将官长看。","祖席又成携手别，离杯何苦上眉酸。","且休凋落高阳社，来往双凫也不难。"]},{"t":"代乐仲和张温甫处督米","f":"七言律诗","c":["未必书生气尽寒，食常不足为居闲。","清于孺子沧浪水，瘦似诗人饭颗山。","欲向田文弹铗去，恐因丘嫂颉羹还。","闻君自有江湖量，肯为枯鱼少破悭。"]},{"t":"清明席上同史正之姚君宝子昂","f":"七言律诗","c":["浮云雨后自纵横，不待风收放晓晴。","百计花期成谩与，一年春色过清明。","谁家钻燧罢藏火，何处吹箫犹卖饧。","回首故园魂欲断，鸟飞只是片时程。"]},{"t":"悼亡","f":"七言律诗","c":["须信人生足别离，别离不待白头时。","因怜曩日在缧绁，岂惮今朝炊扊扅。","中道柰何奔月去，此情惟有落花知。","眼前活计无聊甚，空对当年纸局棋。"]},{"t":"段侯行春显圣观喜雨","f":"七言律诗","c":["行春冠盖暂踌躇，谁信东山面目疏。","兴尽奚劳风送客，气和不觉雨随车。","移民虽恨梁加少，腐粟犹誇汉有馀。","独叹吾儒有何贵，自今牛角莫横书。"]},{"t":"寄荅赵公定","f":"七言律诗","c":["他人共折依依柳，居士但饮薄薄酒。","岂其必取齐之姜，又恐不为白也母。","虽然客或许敦庞，惭愧我无白壁双。","更向稠桑老人卜，准备买红缠酒缸。"]},{"t":"姚子昂寿日","f":"七言律诗","c":["门外风光二月初，衣冠把酒庆悬弧。","一生接物无肠蟹，万事随缘短胫凫。","坐上书空窥草圣，醉中疥壁笑诗奴。","年来世事俱尝遍，只合千金养客躯。"]},{"t":"又用济之韵赠子昂","f":"七言律诗","c":["绵绵宗派自何时，借问吴兴第几支。","书爱换鹅功不到，狱因劾鼠法先知。","为秦徙木思无地，在汉高门福有基。","此去乡闾结仁爱，请君听取忍斋诗。"]},{"t":"为刘益之营中上王怀州 其一","f":"七言律诗","c":["自分毛锥不入时，如今尤恨埽门迟。","徒劳魏氏贪鸡肋，却笑虞人望羖皮。","未有赤心相待处，柰何白发是归期。","傥令扶病还桑梓，横草难忘报所知。"]},{"t":"为刘益之营中上王怀州 其二","f":"七言律诗","c":["毡帐连云逐日移，胡笳月底不胜悲。","中原为患有骄子，造物戏人如小儿。","冯铗纵弹无便去，晏骖未解有谁知。","天涯回首消魂处，故国霜前雁过时。"]},{"t":"锦堂碧落寿席","f":"七言律诗","c":["年光过隙一何忙，知命年来百念忘。","公事了时阴德大，尘缘断后道心凉。","未偿勇退求闲志，先得长生不老方。","共劝十分添寿酒，莫辞酩酊醉山堂。"]},{"t":"答张文玘见戏","f":"七言律诗","c":["邂逅骚人兴愈多，不知赐也许同科。","君犹老去诗魔在，我柰新来技痒何。","但幸近无阿买写，凭谁付与雪儿歌。","一从探得骊珠后，惊倒中洲蚌与蠡。"]},{"t":"和王季文襄阳变后 其一","f":"七言律诗","c":["逐鹿中原未识真，指踪元自有谋臣。","虞全不念唇亡国，楚恐难当舌在人。","拔剑挽回牛斗气，举鞭蹙起汉江尘。","相逢空洒英雄泪，谁是荆州一角麟。"]},{"t":"和王季文襄阳变后 其二","f":"七言律诗","c":["天命须分伪与真，衙蜂战蚁尽君臣。","蛟龙不是池中物，燕雀休嗤垄上人。","衣不能胜嵇绍血，扇无可柰庾公尘。","自从绝笔春秋后，谁复伤时为泣麟。"]},{"t":"僧奴 其一","f":"七言律诗","c":["白发因缘短犊车，可怜小德外家无。","蚌生珠后何嫌老，凤有毛时亦自殊。","会看伯仁兴络秀，不妨节信论潜夫。","刘生谁谓难成事，将相从来有种乎。"]},{"t":"僧奴 其二","f":"七言律诗","c":["喜事相寻种种来，岂期天意一朝回。","璋从弄后熊无梦，月到圆时蚌有胎。","便可字教阿买识，那消钱为窟郎堆。","贤愚怀抱俱休挂，且尽前尊露顶杯。"]},{"t":"和杨之美韵","f":"七言律诗","c":["光华异域仗全才，衔命悤悤出吹台。","物外英标倾水镜，坐中妙语落琼瑰。","节回北阙旋如斗，名振西陲听若雷。","不踏贺兰山下石，国风未合入诗来。"]},{"t":"和李唐杰韵 其一","f":"七言律诗","c":["翰墨场中第一人，而今委翅在鸡群。","纵横诗律凌徐庾，浩污词源媲典坟。","兵气横流存此老，天心未欲器斯文。","年来草就归田赋，啸傲南山卧白云。"]},{"t":"和李唐杰韵 其二","f":"七言律诗","c":["邮筒寄后忆诗人，落落英才迥出群。","试问槐花忙几举，可怜桂子落谁坟。","浮沈且与陪中立，喜愠何尝见子文。","倾破葵心望天表，龙庭不日会风云。"]},{"t":"悼筹堂","f":"七言律诗","c":["霞鞍金辔紫丝绦，玉带红靴织翠袍。","赳赳少年真手臂，津津玉气见眉毫。","不愁造化功难补，可惜秋山势自高。","那免牛车身后患，一场春梦亦徒劳。"]},{"t":"和秦克容来韵","f":"七言律诗","c":["白头羞入利名场，得得归来自远方。","何日诗豪离上党，去年道话忆山阳。","可怜杜宇诉亡国，还笑沐猴思故乡。","不意闲中春色早，黄鹂啼破谢家庄。"]},{"t":"癸酉榜后寄侄谨甫","f":"七言律诗","c":["万轴牙签未是多，十年辛苦短檠歌。","敢忘奕世箕裘业，忽玷清朝甲乙科。","我已梦君三举后，君如输我一筹何。","二疏此去人方识，名字先应报大罗。"]},{"t":"和安斋见寄调祁定之","f":"七言律诗","c":["麻衣补破纸为绦，不羡仙人宫锦袍。","天地老于双转毂，山河渺似一秋毫。","炼深宝鼎丹砂就，瑩彻灵台夜月高。","上界而今官府足，暂游尘世莫辞劳。"]},{"t":"一字百题示商君祥 其一 风","f":"五言绝句","c":["汝未闻天籁，簸扬箕有神。","能清常侍暑，不动庾公尘。"]},{"t":"一字百题示商君祥 其二 月","f":"五言绝句","c":["过圆旁死魄，过缺哉生明。","尚赖玉斧手，再修然后成。"]},{"t":"一字百题示商君祥 其三 云","f":"五言绝句","c":["旱魃将为虐，从龙便出山。","人间三尺雨，命罢早知还。"]},{"t":"一字百题示商君祥 其四 雨","f":"五言绝句","c":["晚有来苏意，忧深望岁人。","一犁虽美满，犹恨不当春。"]},{"t":"一字百题示商君祥 其五 雪","f":"五言绝句","c":["细看花是雨，将见麦宜秋。","度腊无三白，梁园谁与游。"]},{"t":"一字百题示商君祥 其六 山","f":"五言绝句","c":["功名双鬓雪，心事数重山。","山下人家好，终朝爽气閒。"]},{"t":"一字百题示商君祥 其七 泉","f":"五言绝句","c":["滚滚势长往，泠泠味自清。","拟将修水记，何况有诗情。"]},{"t":"一字百题示商君祥 其八 尘","f":"五言绝句","c":["不忧悬榻室，可柰污人风。","踏破青鞋底，犹疑是软红。"]},{"t":"一字百题示商君祥 其九 春","f":"五言绝句","c":["来莫怨春迟，去莫怨春忙。","春不随人老，谁教汝断肠。"]},{"t":"一字百题示商君祥 其十 暑","f":"五言绝句","c":["人间三伏暑，海内一薰风。","独咏微凉句，公权似不公。"]},{"t":"一字百题示商君祥 其十一 寒","f":"五言绝句","c":["广厦千万閒，吾庐弊独寒。","犹将折弦琴，欲和薰风弹。"]},{"t":"一字百题示商君祥 其十二 昼","f":"五言绝句","c":["冬之日何速，夏之日何迟。","山中无历日，迟速两不知。"]},{"t":"一字百题示商君祥 其十三 夜","f":"五言绝句","c":["令乎日之夕，政乎日之朝。","一尊待君子，风雨会良宵。"]},{"t":"一字百题示商君祥 其十四 晴","f":"五言绝句","c":["展尽舒长景，销残片段云。","区区负暄子，炙背不忘君。"]},{"t":"一字百题示商君祥 其十五 阴","f":"五言绝句","c":["朝见白云纵，暮见白云横。","不作及时雨，何为点太清。"]},{"t":"一字百题示商君祥 其十六 花","f":"五言绝句","c":["惜花不论命，看花须努力。","能得几时好，狂风妒春国。"]},{"t":"一字百题示商君祥 其十七 莲","f":"五言绝句","c":["碧因圆更展，红向老犹妆。","镜里风流在，人言似六郎。"]},{"t":"一字百题示商君祥 其十八 菊","f":"五言绝句","c":["色笑秋光淡，香嫌酒力悭。","东篱在何处，客里见南山。"]},{"t":"一字百题示商君祥 其十九 梅","f":"五言绝句","c":["未报江南信，先开雪里村。","要看花上月，立马待黄昏。"]},{"t":"一字百题示商君祥 其二十 松","f":"五言绝句","c":["郁郁愁无地，青青独有心。","疑从大夫后，倾盖到如今。"]},{"t":"一字百题示商君祥 其二十一 竹","f":"五言绝句","c":["潇洒能医俗，檀栾看上番。","我宁负此腹，忍使箨龙冤。"]},{"t":"一字百题示商君祥 其二十二 草","f":"五言绝句","c":["日没露易湿，日出露易晞。","人生大都几，王孙胡不归。"]},{"t":"一字百题示商君祥 其二十三 燕","f":"五言绝句","c":["社后来何暮，梁閒话颇多。","巢泥愁未稳，无面见淘河。"]},{"t":"一字百题示商君祥 其二十四 雁","f":"五言绝句","c":["俄见天边字，徒销客里魂。","一书言不尽，为我叙寒温。"]},{"t":"一字百题示商君祥 其二十五 鸥","f":"五言绝句","c":["江静烟笼雪，天晴水浴衣。","渔歌惊不起，物外两忘机。"]},{"t":"一字百题示商君祥 其二十六 鹤","f":"五言绝句","c":["去家丁令威，化身徐佐卿。","不恋乘轩宠，九皋堪一鸣。"]},{"t":"一字百题示商君祥 其二十七 蜂","f":"五言绝句","c":["弄晴沾落絮，带雨护园花。","有课常输蜜，无春不到衙。"]},{"t":"一字百题示商君祥 其二十八 蝶","f":"五言绝句","c":["元从生处乐，肯向死前休。","花底人閒世，如何不梦周。"]},{"t":"一字百题示商君祥 其二十九 龟","f":"五言绝句","c":["汝壳将自遮，汝肠还自刳。","可怜一底板，虽智不如愚。"]},{"t":"一字百题示商君祥 其三十 鱼","f":"五言绝句","c":["华亭载月船，长安遮日手。","一网腥城市，吾于尔何有。"]},{"t":"一字百题示商君祥 其三十一 蟹","f":"五言绝句","c":["食必视本草，贵在精物理。","蔡侯何卤莽，几为勤学死。"]},{"t":"一字百题示商君祥 其三十二 儒","f":"五言绝句","c":["秦坑秦即孤，鲁戏鲁寻削。","伊谁蹈前轨，可谓束高阁。"]},{"t":"一字百题示商君祥 其三十三 僧","f":"五言绝句","c":["貌与松俱瘦，心将絮共沾。","一庵空寂地，香火读楞严。"]},{"t":"一字百题示商君祥 其三十四 道","f":"五言绝句","c":["自知身是患，常谓道无名。","欲作闲中友，随缘论养生。"]},{"t":"一字百题示商君祥 其三十五 仙","f":"五言绝句","c":["千载辽东鹤，双飞叶县凫。","应怜尘世里，无地著臞儒。"]},{"t":"一字百题示商君祥 其三十六 禅","f":"五言绝句","c":["见桃浑不悟，对柏未尝参。","虎啸龙吟子，风雷振一龛。"]},{"t":"一字百题示商君祥 其三十七 医","f":"五言绝句","c":["愈风陈有檄，止疟杜能诗。","虽然医者意，何意亦何医。"]},{"t":"一字百题示商君祥 其三十八 卜","f":"五言绝句","c":["弃置复弃置，其然岂其然。","百钱聊为我，更看小行年。"]},{"t":"一字百题示商君祥 其三十九 渔","f":"五言绝句","c":["一声歌欸乃，万顷国烟波。","鳌蟹中间醉，蓑衣拜浪婆。"]},{"t":"一字百题示商君祥 其四十 樵","f":"五言绝句","c":["云外山将遍，人閒日易斜。","不知棋换世，柯烂未还家。"]},{"t":"一字百题示商君祥 其四十一 客","f":"五言绝句","c":["渺渺亡羊路，悠悠化鹤身。","人閒同逆旅，谁主复谁宾。"]},{"t":"一字百题示商君祥 其四十二 农","f":"五言绝句","c":["卖剑田园计，温家种树书。","新年无罪岁，事事有乘除。"]},{"t":"一字百题示商君祥 其四十三 牧","f":"五言绝句","c":["蓑底因缘曲，腰閒觳觫鞭。","月明归去晚，想见葛洪川。"]},{"t":"一字百题示商君祥 其四十四 射","f":"五言绝句","c":["手撚金仆姑，身出矍相圃。","不穿百步杨，志在猖狂虏。"]},{"t":"一字百题示商君祥 其四十五 猎","f":"五言绝句","c":["终日无获禽，古人猎在德。","非德为禽荒，猎食吾不食。"]},{"t":"一字百题示商君祥 其四十六 诗","f":"五言绝句","c":["裁作牛腰束，愁于饭颗山。","近觉故步窘，十债九不还。"]},{"t":"一字百题示商君祥 其四十七 书","f":"五言绝句","c":["入室五千卷，插架三万轴。","何似晒书人，坦此便便腹。"]},{"t":"一字百题示商君祥 其四十八 笔","f":"五言绝句","c":["不见中书君，不闻老成人。","为君作佳传，继者皆尖新。"]},{"t":"一字百题示商君祥 其四十九 墨","f":"五言绝句","c":["松閒老潘谷，何处得玄圭。","速置蔷薇露，诗仙醉欲题。"]},{"t":"一字百题示商君祥 其五十 纸","f":"五言绝句","c":["慇勤翰林主，挥埽惊风雨。","滴滴是玄珠，点破先生楮。"]},{"t":"一字百题示商君祥 其五十一 砚","f":"五言绝句","c":["端溪温润石，价重百车渠。","一滴玄潭水，蝇头万卷书。"]},{"t":"一字百题示商君祥 其五十二 画","f":"五言绝句","c":["有意皆堪谱，无言总是诗。","潭潭居相府，此誉不妨驰。"]},{"t":"一字百题示商君祥 其五十三 琴","f":"五言绝句","c":["阴壑鸣松籁，空岩响石泉。","此声并此意，谁得寄徽弦。"]},{"t":"一字百题示商君祥 其五十四 棋","f":"五言绝句","c":["纵横连井地，明暗列星图。","两角触蛮战，一家瓜葛无。"]},{"t":"一字百题示商君祥 其五十五 剑","f":"五言绝句","c":["带牛移汉俗，匣刃出酆城。","安得治复古，器农不器兵。"]},{"t":"一字百题示商君祥 其五十六 香","f":"五言绝句","c":["小炷博山鼎，半残心字灰。","游蜂何处客，应为百花来。"]},{"t":"一字百题示商君祥 其五十七 茶","f":"五言绝句","c":["人多愁水厄，若个有诗情。","灵草还知我，平生事不平。"]},{"t":"一字百题示商君祥 其五十八 师","f":"五言绝句","c":["绛帐风流远，青襟礼貌骄。","定须防射羿，何必问嘲韶。"]},{"t":"一字百题示商君祥 其五十九 学","f":"五言绝句","c":["邑化弦歌地，邻渐俎豆风。","二三言志子，六七咏归童。"]},{"t":"一字百题示商君祥 其六十 仕","f":"五言绝句","c":["虽有乘桴意，能忘出昼情。","一官百僚底，是亦道之行。"]},{"t":"一字百题示商君祥 其六十一 富","f":"五言绝句","c":["狼籍胡椒斛，破散堆钱屋。","不见贪者愚，求荣是求辱。"]},{"t":"一字百题示商君祥 其六十二 贵","f":"五言绝句","c":["鸱得腐鼠嚇，犬笑狡兔死。","唾手功名场，不知忧患始。"]},{"t":"一字百题示商君祥 其六十三 贫","f":"五言绝句","c":["书生禄有籍，造物费亦省。","颜回一箪食，不得尽晚景。"]},{"t":"一字百题示商君祥 其六十四 隐","f":"五言绝句","c":["孔负二宜去，嵇知七不堪。","青山休老地，佳处是终南。"]},{"t":"一字百题示商君祥 其六十五 智","f":"五言绝句","c":["乐在知几早，忧因见道迟。","遥怜鲍庄子，人笑不如葵。"]},{"t":"一字百题示商君祥 其六十六 愚","f":"五言绝句","c":["膏以明自煎，薰以香自薪。","善哉柳侯意，一字辱溪神。"]},{"t":"一字百题示商君祥 其六十七 寿","f":"五言绝句","c":["灰如恋阙心，雪似穷经首。","问年今几何，看饮屠酥酒。"]},{"t":"一字百题示商君祥 其六十八 老","f":"五言绝句","c":["尊年乡饮礼，击壤太平歌。","甲子君休问，光阴得最多。"]},{"t":"一字百题示商君祥 其六十九 名","f":"五言绝句","c":["求为天下士，所望不亦厚。","得少失有馀，何况在身后。"]},{"t":"一字百题示商君祥 其七十 友","f":"五言绝句","c":["偶因势贵贱，乃见朋得丧。","岁寒山阴雪，独有戴可访。"]},{"t":"一字百题示商君祥 其七十一 身","f":"五言绝句","c":["黄卷平生志，青山见在缘。","百年令已半，只合斗樽前。"]},{"t":"一字百题示商君祥 其七十二 影","f":"五言绝句","c":["相对镜中真，相随月下人。","我今未忘我，身外还见身。"]},{"t":"一字百题示商君祥 其七十三 行","f":"五言绝句","c":["水笑杯犹渡，山惊锡尚飞。","垂垂瓶钵老，何处未来归。"]},{"t":"一字百题示商君祥 其七十四 住","f":"五言绝句","c":["俗尚家灵运，谁堪社远公。","空山云不出，愁杀渡溪风。"]},{"t":"一字百题示商君祥 其七十五 坐","f":"五言绝句","c":["一轩容膝安，半世行脚债。","庞家老居士，举似无生话。"]},{"t":"一字百题示商君祥 其七十六 卧","f":"五言绝句","c":["一室散天花，一榻飏茶烟。","家风嗣阿谁，残月晓风禅。"]},{"t":"一字百题示商君祥 其七十七 笑","f":"五言绝句","c":["和气须欢伯，开颜只孔方。","世情如苦海，件件可鬨堂。"]},{"t":"一字百题示商君祥 其七十八 吟","f":"五言绝句","c":["冥搜肠亦苦，只字得之难。","作者有六义，惜哉坐一寒。"]},{"t":"一字百题示商君祥 其七十九 醉","f":"五言绝句","c":["爱此真珠滴，能于大道通。","与君同举白，怜我独潮红。"]},{"t":"一字百题示商君祥 其八十 醒","f":"五言绝句","c":["暂出陶陶境，那禁种种愁。","举觞邀明月，却带醉乡侯。"]},{"t":"一字百题示商君祥 其八十一 饮","f":"五言绝句","c":["竹叶杯中醁，金钗坐上春。","浅斟低唱境，犹道是粗人。"]},{"t":"一字百题示商君祥 其八十二 舞","f":"五言绝句","c":["野鹤闻琴态，孤鸾对镜妍。","为君小垂手，无地可回旋。"]},{"t":"一字百题示商君祥 其八十三 睡","f":"五言绝句","c":["客随陶令遣，斋甚太常严。","傥或非黄奶，那知此黑甜。"]},{"t":"一字百题示商君祥 其八十四 梦","f":"五言绝句","c":["物外日月忙，人閒忧患长。","休谈梦中梦，万古一黄粱。"]},{"t":"一字百题示商君祥 其八十五 歌","f":"五言绝句","c":["大音声自希，赏音人亦寡。","宁可逆汝耳，不可废作者。"]},{"t":"一字百题示商君祥 其八十六 啸","f":"五言绝句","c":["成瑨风生坐，孙登月满台。","东皋今寂寞，元亮早归来。"]},{"t":"一字百题示商君祥 其八十七 傲","f":"五言绝句","c":["王公轻以道，富贵骄以志。","我见高尚人，盖有高尚事。"]},{"t":"一字百题示商君祥 其八十八 闲","f":"五言绝句","c":["太傅悬车里，仙家避世壶。","老妻为纸局，坐隐是功夫。"]},{"t":"一字百题示商君祥 其八十九 懒","f":"五言绝句","c":["交有书堪绝，师何记可嘲。","不僧亦不俗，似痴还似高。"]},{"t":"一字百题示商君祥 其九十 话","f":"五言绝句","c":["万事就庾谈，一心对芝宇。","不思炊作麋，但见风生麈。"]},{"t":"一字百题示商君祥 其九十一 浴","f":"五言绝句","c":["子春恐事败，佟之坐水淫。","二者过不及，何如我洗心。"]},{"t":"一字百题示商君祥 其九十二 归","f":"五言绝句","c":["世路虽多梗，吾生岂系匏。","西风倦飞翼，乐在一枝巢。"]},{"t":"一字百题示商君祥 其九十三 别","f":"五言绝句","c":["更尽一杯酒，出门行路难。","送君过南浦，忍泪凭栏干。"]},{"t":"一字百题示商君祥 其九十四 愁","f":"五言绝句","c":["解使回肠断，能催两鬓秋。","天涯未归客，容易上眉头。"]},{"t":"一字百题示商君祥 其九十五 忍","f":"五言绝句","c":["气留脐可煖，唾使面自乾。","无怨亦无恶，此腹如此宽。"]},{"t":"一字百题示商君祥 其九十六 蚕","f":"五言绝句","c":["蚕月始条桑，悤悤妇姑忙。","天寒授衣节，妇姑无完裳。"]},{"t":"一字百题示商君祥 其九十七 织","f":"五言绝句","c":["泛槎惊误客，折齿笑狂邻。","不作回文字，愁嫌愁杀人。"]},{"t":"一字百题示商君祥 其九十八 舂","f":"五言绝句","c":["断木才脱粟，湿薪空爆竹。","朝餐动及午，柰此雷鸣腹。"]},{"t":"一字百题示商君祥 其九十九 炊","f":"五言绝句","c":["旅食寄天涯，愁如桂玉何。","莫忘生处乐，听取扊扅歌。"]},{"t":"一字百题示商君祥 其一○○ 砧","f":"五言绝句","c":["对影无情石，关心寄远衣。","天涯镇长客，雁后不怀归。"]},{"t":"和筹堂四首 其一 琴","f":"五言绝句","c":["山水有清音，琅然出枯木。","若教俗耳听，丝竹不如肉。"]},{"t":"和筹堂四首 其二 棋","f":"五言绝句","c":["森森戈戟心，尽在皮里著。","傍有烂柯人，点破都是错。"]},{"t":"和筹堂四首 其三 书","f":"五言绝句","c":["一坑科斗灰，难破祖龙惑。","三两挟策人，今谁席肯侧。"]},{"t":"和筹堂四首 其四 画","f":"五言绝句","c":["手与心相应，妙处在咫尺。","笔尖多少锋，挥埽天地窄。"]},{"t":"东郊行","f":"五言绝句","c":["四海尚干戈，几人知稼穑。","青青原上麦，忍放征马食。"]},{"t":"书壁","f":"五言绝句","c":["世事纷纷变，人生种种愁。","行年三十九，得岁又平头。"]},{"t":"避乱","f":"五言绝句","c":["雪岩依日煖，霜树弄风悲。","山似王维画，人如杜甫诗。"]},{"t":"资圣寺壁","f":"五言绝句","c":["是谁将壁疥，尽可著纱笼。","今代无诗史，何时入国风。"]},{"t":"别陈之纲李得之南子荣","f":"五言绝句","c":["已兆池鱼祸，尚多风鹢过。","寄与远游人，莫待赆行货。"]},{"t":"戏高广之","f":"五言绝句","c":["一饮遇伶妇，一饭值丘嫂。","徒教乞米僧，时时送卢老。"]},{"t":"雨后","f":"五言绝句","c":["新秋积雨霁，凉风吹我衣。","岁月不知老，乾坤何处归。"]},{"t":"九日答朱寿之","f":"五言绝句","c":["与客登高处，节物伤迟暮。","不见白衣来，三复秋风句。"]},{"t":"竹林","f":"五言绝句","c":["初见锦绷脱，气已傲霜雪。","天寒十万夫，未闻一死节。"]},{"t":"柏径","f":"五言绝句","c":["岁晚节自抱，足见有心哉。","游人从何处，带得春风来。"]},{"t":"槐亭","f":"五言绝句","c":["蚁穴功名重，或作封侯梦。","主人心已闲，不为黄花动。"]},{"t":"稻塍","f":"五言绝句","c":["一水自纵横，厥田无上下。","居民不佩犊，岁事在秧马。"]},{"t":"儒","f":"五言绝句","c":["世治其术重，世乱其术轻。","太平然后用，用然后太平。"]},{"t":"蝶","f":"五言绝句","c":["转首一场梦，惊心三月春。","扬扬枝上蝶，不见惜花人。"]},{"t":"熊白","f":"五言绝句","c":["所居无禹庙，有官升典签。","掌亦我所欲，二者不可兼。"]},{"t":"十六日夜戏书","f":"五言绝句","c":["贪作梅花梦，都忘柳絮禅。","可怜人与月，不似夜来圆。"]},{"t":"雪庵题钱过庭梅花图","f":"曲","c":["已把传神画谱，又看格在诗评。","月落难寻清梦，云空乃见高情。"]},{"t":"示侄辈","f":"曲","c":["诸阮以富相誇，二疏恐财为病。","济叔不羡金埒，绩兄曾有挝命。"]},{"t":"渊明归去来图","f":"曲","c":["先生从来寄傲，肯向小儿鞠躬。","笑指田园归去，门前五柳春风。"]},{"t":"中秋","f":"曲","c":["三百六旬岁周，一十二度月圆。","试问姮娥甲子，和闰到今几年。"]},{"t":"郎文炳心远斋","f":"曲","c":["窃笑滥巾北岳，那能补衲中条。","自有胸中丘壑，不妨稳向市朝。"]},{"t":"伯德仲植张长史帖","f":"曲","c":["莫就严陵买菜，无劳逸少换鹅。","但得云烟一纸，那在邺侯书多。"]},{"t":"戏沂公巨川","f":"曲","c":["八仙诗里苏晋，三笑图中远公。","选甚逃禅破戒，我师自有家风。"]},{"t":"戏武夫韩公 其一","f":"曲","c":["论功终是猎犬，见事不如擒虎。","我愿一识荆州，人道莫逢玉汝。"]},{"t":"戏武夫韩公 其二","f":"曲","c":["结柳未送穷车，弊衣先入歌院。","虽得萧何指踪，难与老子同传。"]},{"t":"老杜醉归图 其一","f":"曲","c":["寻常行处酒债，每日江头醉归。","薄暮斜风细雨，长安一片花飞。"]},{"t":"老杜醉归图 其二","f":"曲","c":["百钱街头酒价，蹇驴醉里风光。","莫傍郑公门去，恐犹恨在登床。"]},{"t":"史遂良酒债 其一","f":"曲","c":["都因焚券家贫，亲与当炉人卖。","问得街头酒价，索取江头酒债。"]},{"t":"史遂良酒债 其二","f":"曲","c":["酒诰一篇既出，离骚亦可不作。","愧我家无阿堵，笑他人饮狂药。"]},{"t":"史遂良酒债 其三","f":"曲","c":["涤器不辞亲酌，过门无柰客恶。","未尝解下金龟，必能画得黄鹤。"]},{"t":"史遂良酒债 其四","f":"曲","c":["从来欢伯气和，何故督邮味恶。","陶令无钱但赊，潘子著水不错。"]},{"t":"窦子温江山图","f":"曲","c":["醉里扁舟烟浪，望中几屐云山。","长天秋水一色，明月清风两閒。"]},{"t":"猫犬图","f":"曲","c":["狡兔空有三穴，首鼠漫持两端。","我辈天生健武，从渠股慄心寒。"]},{"t":"北窗高卧图","f":"曲","c":["问字不得兀兀，借书不得陶陶。","谁遣人来送酒，枕边正读离骚。"]},{"t":"雪谷早行图","f":"曲","c":["积素茫茫缟夜，流光耿耿扬辉。","行人抵死贪路，何处家山未归。"]},{"t":"史正之器子买得","f":"曲","c":["陆郎初见怀橘，阿买颇解识字。","或恐西河器明，忙为东野收泪。"]},{"t":"灵照女","f":"曲","c":["留下一重公案，有女谁似庞家。","不试提蓝手段，若为点破丹霞。"]},{"t":"锦堂四景图 其一 春水满四泽","f":"曲","c":["淼淼舒如罗带，鳞鳞皱似縠纹。","谁道卧龙不起，须臾变化风云。"]},{"t":"锦堂四景图 其二 夏云多奇峰","f":"曲","c":["幸得从龙变态，尚何出岫无心。","正苦人閒畏日，不思天上为霖。"]},{"t":"锦堂四景图 其三 秋月扬明辉","f":"曲","c":["清光一片如洗，西去姮娥耐秋。","可惜广寒人老，谁将玉斧再修。"]},{"t":"锦堂四景图 其四 冬岭秀孤松","f":"曲","c":["山前倾盖独奇，雪里盘根岁深。","千年老鹤相伴，谁似苍髯有心。"]},{"t":"谒秦吴二王庙 其一","f":"七言绝句","c":["颓垣陊殿夕阳中，血食虽同事不同。","揖让干戈两陈迹，酹觞抛与落花风。"]},{"t":"谒秦吴二王庙 其二","f":"七言绝句","c":["杖藜行处记曾过，草草杯盘野兴多。","举目山川纵如旧，一场梦抵几南柯。"]},{"t":"卜居","f":"七言绝句","c":["东邻西舍两三家，簌簌墙头落枣花。","惭愧画梁双燕子，笑人今日又天涯。"]},{"t":"中秋夜梦","f":"七言绝句","c":["征衣不用赠春罗，试听尊前一曲歌。","为问从来云雨事，如何偏向梦中多。"]},{"t":"读项羽传","f":"七言绝句","c":["鸿沟时暂割山河，楚国山河一半多。","欲去故乡誇富贵，不知沛有大风歌。"]},{"t":"糟笋","f":"七言绝句","c":["瓮中有地可藏真，子子孙孙曲糵醺。","谁是圣之清者后，此君应负此君君。"]},{"t":"新样团茶","f":"七言绝句","c":["春风倾倒在灵芽，才到江南百草花。","未试人閒小团月，异香先入玉川家。"]},{"t":"重午偶题","f":"七言绝句","c":["只为离骚话独清，至今犹恨楚君臣。","魂招不得归何处，闲气都留与艾人。"]},{"t":"子猷访戴图","f":"七言绝句","c":["雪后山阴本乘兴，似非特为故人来。","纵能一见戴安道，船未回时心己回。"]},{"t":"和筹堂途中即事 其一","f":"七言绝句","c":["晚风吹雨过山堂，灯火秋凉好对床。","却被荒鸡笑人懒，一声催起著鞭忙。"]},{"t":"和筹堂途中即事 其二","f":"七言绝句","c":["悠悠旌旆出山城，世事惊心几变更。","水郭烟村谁是伴，老夫矍铄尚堪行。"]},{"t":"和筹堂途中即事 其三","f":"七言绝句","c":["斗酒中閒诗百篇，锦囊新句落谁边。","无穷山水吟难尽，说似画师僧巨然。"]},{"t":"船子和月图","f":"七言绝句","c":["千尺丝纶在手中，月明归去满船空。","寒江岂是鱼难钓，钓得还将不钓同。"]},{"t":"和河楼闲望 其一","f":"七言绝句","c":["去去来来不系舟，至今师渡几时休。","洗兵岂是天无雨，尽逐黄河入海流。"]},{"t":"和河楼闲望 其二","f":"七言绝句","c":["一夜长空落将星，不知谁抱越人冰。","中原可惜衣冠地，自古以来多废兴。"]},{"t":"用筹堂韵","f":"七言绝句","c":["清尊莫惜再三开，别后何曾得好怀。","为向绿衣花使道，杖藜不是等闲来。"]},{"t":"答满法师","f":"七言绝句","c":["此身分付水云閒，不见高人得句难。","待学江西立公案，便宜筑个小诗坛。"]},{"t":"和泰禅","f":"七言绝句","c":["淡泊生涯分自甘，十年霜叶碎青衫。","忽从问道山前过，牧马之儿是指南。"]},{"t":"橙数珠 其一","f":"七言绝句","c":["典刑酿出洞庭霜，只取青圆不待黄。","凡俗尽从千佛转，忘言老宿但拈香。"]},{"t":"橙数珠 其二","f":"七言绝句","c":["从头细转梵王经，一串秋香得洞庭。","为报重苏当自惜，莫教落入念珠厅。"]},{"t":"竹如意 其一","f":"七言绝句","c":["曾为弹琴指甲伤，有时曝背竹书光。","不须爬痒倩仙爪，忍待一朝春笋长。"]},{"t":"竹如意 其二","f":"七言绝句","c":["即时参得指头禅，说似家风玉版传。","一日佛堂光自放，我师歇在古灵前。"]},{"t":"雪庵二梅图","f":"七言绝句","c":["老对风光百不堪，画图彷佛见江南。","为君试草花閒赋，未必心肠似雪庵。"]},{"t":"赠碧落和讲主","f":"七言绝句","c":["萧萧古寺掩松关，雨后无人草木闲。","埽地家风谁举似，我师特特为开山。"]},{"t":"跋窦子温江山图","f":"七言绝句","c":["淼淼澄江欲拍天，参差烟树老江边。","举头不见长安日，一棹秋风载酒船。"]},{"t":"济源龙潭","f":"七言绝句","c":["尘世悠悠不识真，一潭春碧养潜鳞。","可怜无故惊雷起，误却山前失箸人。"]},{"t":"裴公亭","f":"七言绝句","c":["青山如画水如蓝，自笑平生性僻耽。","尊酒留连妨逸兴，不能一到侍中庵。"]},{"t":"与奉仙观道士元明道","f":"七言绝句","c":["野鹤飘飘性自高，徘徊尘世岂难抛。","栖真旧隐无多地，何处仙山不可巢。"]},{"t":"富公草堂","f":"七言绝句","c":["青山重叠水萦回，山水中閒几往来。","风物不殊人世改，中州何处是昆台。"]},{"t":"谢杨成之","f":"七言绝句","c":["与客西从济上回，明朝扶杖到云台。","一尊相送休频劝，留作山行软脚杯。"]},{"t":"阻风","f":"七言绝句","c":["东风作恶几时休，况值春光欲尽头。","谁谓闲人无个事，一年长是为花愁。"]},{"t":"答筹堂见招 其一","f":"七言绝句","c":["须信人閒足别离，相看能得几多时。","浮云一片无根蒂，去去来来自不知。"]},{"t":"答筹堂见招 其二","f":"七言绝句","c":["日日相陪鹤发翁，乌纱白葛道家风。","火云堆向山南去，暑气蒸人似甑中。"]},{"t":"答筹堂见招 其三","f":"七言绝句","c":["俯仰随人亦自欺，精神无复似当时。","年来世事俱尝遍，只有闲中味不知。"]},{"t":"答筹堂见招 其四","f":"七言绝句","c":["冠世声名盖世功，寻常杯酒坐生风。","区区问舍求田客，尽在元龙一笑中。"]},{"t":"答筹堂见招 其五","f":"七言绝句","c":["日日言归未得归，白头才是入山时。","依前却趁逍遥出，惭愧山灵我不知。"]},{"t":"答筹堂见招 其六","f":"七言绝句","c":["谁谓长河不可通，只消送客一帆风。","故人别后情偏重，犹恐相逢是梦中。"]},{"t":"史遂良寿日","f":"七言绝句","c":["任他白发不相饶，两颊春红醉里潮。","今日凤凰台上月，未知谁可共吹箫。"]},{"t":"和王季文襄阳变后","f":"七言绝句","c":["将军横槊面潮红，一举淮南埽地空。","堪笑楚人无伎俩，至今犹说马牛风。"]},{"t":"张翔卿出家","f":"七言绝句","c":["绛帕蒙头读道书，孙郎见后肯容无。","休将侥倖乖名教，天上臞仙即是儒。"]},{"t":"鳌背元夜","f":"七言绝句","c":["山市家家秉烛游，风檐齐挂月灯毬。","不须更用闲妆点，人在鳌峰最上头。"]},{"t":"许司谏醉吟图","f":"七言绝句","c":["席地风光引兴来，不辞白发被春催。","眼前有句贪拈掇，闲却梨花树下杯。"]},{"t":"明皇击梧图","f":"七言绝句","c":["不使梨园弟子知，太平音在凤凰枝。","一朝野鹿衔花去，长恨秋风落叶时。"]},{"t":"秋江断雁图","f":"七言绝句","c":["不堪愁里见秋光，江北江南木叶黄。","谁信朔风犹跋扈，天涯吹断弟兄行。"]},{"t":"游石堂山","f":"七言绝句","c":["雨后青山画不如，算心人去有谁居。","紫云空锁神清洞，不见丹崖四字书。"]},{"t":"句龙庙","f":"七言绝句","c":["溪行十里气如蒸，危槛凭虚不厌登。","咫尺仙山在尘世，杖藜来往几人曾。"]},{"t":"阳关图","f":"七言绝句","c":["一杯送别古阳关，关外千重万叠山。","试问青青渭城柳，不知眼见几人还。"]},{"t":"烟江叠嶂图","f":"七言绝句","c":["挥毫落纸生云烟，江北江南水墨天。","爱画主人胸次别，卧游不用买山钱。"]},{"t":"千里江山图 其一","f":"七言绝句","c":["曾把云山烂漫酬，杖藜随处贾胡留。","如今脚力那千里，水墨中间只卧浮。"]},{"t":"千里江山图 其二","f":"七言绝句","c":["笔下江山取意成，一峰未尽一峰生。","凭谁试向行人问，水郭烟村第几程。"]},{"t":"荅祁定之","f":"七言绝句","c":["归袖迎风拂面埃，青山望处白云埋。","如何千载离家鹤，学得仙时不便来。"]},{"t":"戏赠","f":"七言绝句","c":["布袍褴褛化风埃，是处青山骨可埋。","三笑家风□时了，我师容易去还来。"]},{"t":"雪中寄","f":"七言绝句","c":["秋空一洗绝纤埃，著脚街头雪半埋。","试问希真门下客，衣蓑曾有葛三来。"]},{"t":"不寐","f":"七言绝句","c":["露下中庭鹤睡惊，娟娟缺月照窗明。","夜深读罢床头易，纸帐梅花梦不成。"]},{"t":"西山问羊","f":"七言绝句","c":["淡泊不禁频皛饭，寻常无以致毡根。","西山茧耳多于石，肯与书生踏菜园。"]},{"t":"暮秋有感","f":"七言绝句","c":["乱鸦无数噪寒林，林下风吹落叶深。","惟有黄花枝上露，向人犹似泣残金。"]},{"t":"即事","f":"七言绝句","c":["将军下马气如虹，书生折腰曲如弓。","好山无限归未得，白云惭愧渡溪风。"]},{"t":"即事","f":"七言绝句","c":["秋色南山气势高，坐閒牛酒话粗豪。","自怜萍梗天涯客，俯仰随人似桔槔。"]},{"t":"陆浑佛髻山","f":"七言绝句","c":["十步都无一步平，往来人似画图行。","可怜一派温泉水，不与荒山洗恶名。"]},{"t":"汤下寺壁","f":"七言绝句","c":["滚滚龙泉自吐吞，谁能个里混光尘。","再三绕壁寻题句，饶舌山禽不避人。"]},{"t":"跋背面弥勒","f":"七言绝句","c":["万水千山特特来，谩劳皮袋走尘埃。","横担柱杖明州去，世上谁能唤得回。"]},{"t":"题断碑","f":"七言绝句","c":["节角催残卧夕阳，岂无神物护文章。","一从荐福雷轰后，片石犹争日月光。"]},{"t":"游青莲□值巨川彦广二上人出","f":"七言绝句","c":["寂寂荒庭落叶堆，与谁重上远公台。","青山不解留人住，立尽秋风曦未来。"]},{"t":"戏曹汉臣 其一","f":"七言绝句","c":["一见高僧话亦高，醉中往往爱禅逃。","尔曹自谓曹溪后，不怕曹溪笑尔曹。"]},{"t":"戏曹汉臣 其二","f":"七言绝句","c":["移得花将碧落栽，一枝开后百枝开。","今生也有狂灵运，待入东林社里来。"]},{"t":"碧落院松","f":"七言绝句","c":["霜干亭亭耸碧空，几年春雨养髯龙。","也能说得菩提法，何处人閒有万松。"]},{"t":"雪后送宝泉之碧落","f":"七言绝句","c":["洒面轻风不觉寒，天花散落满人閒。","慇勤行脚休辞远，出得城门是雪山。"]},{"t":"陶学士烹茶图","f":"七言绝句","c":["□□天寒对酪奴，竹閒雪鼎与风炉。","书生事业真堪□，□谓粗人此景无。"]},{"t":"修武骞林观","f":"七言绝句","c":["□□带雨阻登临，往事看碑或可寻。","不是青牛洞中□，人閒何处有鶱林。"]},{"t":"射虎","f":"七言绝句","c":["逐鹿中原鹿已无，功名那在一于菟。","分明射中南山虎，李广元来不丈夫。"]},{"t":"答筹堂 其一","f":"七言绝句","c":["休嫌堂上聚星迟，邂逅人生似有时。","鸡黍恐忘今后约，预先报与巨卿知。"]},{"t":"答筹堂 其二","f":"七言绝句","c":["秋凉急急授衣迟，便是霜林叶落时。","夜听寒砧动离思，恨无针线小蛮知。"]},{"t":"参谋王君玉魏文侯冒雨出猎图","f":"七言绝句","c":["□□冒雨入山林，毕竟驰驱获几禽。","自是魏侯言不负，当时只合献虞箴。"]},{"t":"抱树石","f":"七言绝句","c":["火馀介子身犹在，槁立鲍焦心愈坚。","欲向前村问遗叟，石荒树老不知年。"]},{"t":"和王成之梅韵 其一","f":"七言绝句","c":["踏雪寻芳路带沙，南枝初放两三花。","高楼寄语休吹笛，留取春风与大家。"]},{"t":"和王成之梅韵 其二","f":"七言绝句","c":["朝来一雪羃晴沙，行到前村始见花。","驿使便将春色去，暗香今夜落谁家。"]},{"t":"狂风","f":"七言绝句","c":["春光著物酒如浓，白白红红眼界中。","又是一场蝴蝶梦，能禁几度落花风。"]},{"t":"游锦堂后园","f":"七言绝句","c":["妆点园林次第新，野花无数不知名。","即时唤起闲中兴，惭愧陶家趣未成。"]},{"t":"袁景先东归丧马 其一","f":"七言绝句","c":["汗血奔驰死即休，东郊骨骼有谁收。","举鞭遥指前山路，野草闲花满地愁。"]},{"t":"袁景先东归丧马 其二","f":"七言绝句","c":["长鞦短辔惯骑驴，今日徒行为的颅。","得失从来等闲事，未知愁得塞翁无。"]},{"t":"玉李花","f":"七言绝句","c":["盘根春后几枝分，似比树头花更新。","落月试将颜色照，便如传得谪仙神。"]},{"t":"半丈红","f":"七言绝句","c":["艳冷香清是就中，等闲不肯媚春风。","东君也恨无颜色，染出枝头点点红。"]},{"t":"溪竹","f":"七言绝句","c":["崎岖一径逐溪斜，泛泛溪流带落花。","为问风前双燕子，衔泥飞去入谁家。"]},{"t":"吴神","f":"七言绝句","c":["山头多少往来人，香火争将瓦鼎焚。","箫鼓下山人渐远，晚风吹起一溪云。"]},{"t":"过古寨","f":"七言绝句","c":["系马垂杨日半斜，荒村篱落两三家。","可怜华屋生存处，瓦砾堆中几树花。"]},{"t":"大阳与诸友话旧","f":"七言绝句","c":["寻芳来入杏花村，见客人人有典刑。","不用看碑问前事，坐中一话即图经。"]},{"t":"听乐","f":"七言绝句","c":["闻韶还似在齐时，三月犹然味不知。","若要得他安乐法，请君听取四休诗。"]},{"t":"郜氏院看花","f":"七言绝句","c":["□□花枝不耐寒，就中姚魏欲开难。","赏心未惬空归去，更待明朝烂漫看。"]},{"t":"长平怀古","f":"七言绝句","c":["赵括虽能读父书，长平一举见规模。","纵横战国俱陈迹，只有青山似画图。"]},{"t":"枯松","f":"七言绝句","c":["为嫌红紫污家风，故向春来学种松。","祗恐等闲儿女辈，辄将斤斧损髯龙。"]},{"t":"劝行","f":"七言绝句","c":["谁肯收心醉六经，只言酒是在天星。","若能读得离骚后，学取先生半日醒。"]},{"t":"游青莲分韵得春字","f":"七言绝句","c":["四面山围故故青，茶烟榻畔坐忘身。","与师贪论安心法，门外飞花送却春。"]},{"t":"慈氏阁","f":"七言绝句","c":["金碧相辉跨杳冥，凭高伫目记吾曾。","劝君试倚栏干望，愧我今无脚力登。"]},{"t":"出山 其一","f":"七言绝句","c":["兴尽东山命驾忙，断云似与雨商量。","出门卷地颠风起，送客何须尔许狂。"]},{"t":"出山 其二","f":"七言绝句","c":["东林景物画中诗，老恨因循著脚迟。","背了青山却归去，头灰面土任风吹。"]},{"t":"水帘","f":"七言绝句","c":["倒倾蛟室泻琼瑰，派落空岩雪浪堆。","卷地封姨收不起，素娥垂下玉钩来。"]},{"t":"柳 其一","f":"七言绝句","c":["一年春色到溪头，展尽眉閒几点愁。","才得东君暂时意，笑他张绪不风流。"]},{"t":"柳 其二","f":"七言绝句","c":["千丝万缕弄风柔，为爱春阴尽日留。","杖屦重来有佳处，道人凿石沼清流。"]},{"t":"临清台 其一","f":"曲","c":["忽惊平地一声雷，烁烁骄阳气欲回。","安得霶?片时雨，临清台是望云台。"]},{"t":"临清台 其二","f":"七言绝句","c":["登山兴尽早宜归，况是东风送客时。","只有临清台下水，怪人来此不留诗。"]},{"t":"怀旧","f":"七言绝句","c":["杖藜重到古招提，硖石云深一径迷。","不见同来旧时伴，怕看双翠壁閒题。"]},{"t":"新安","f":"七言绝句","c":["芳草原头一望空，村南村北落花风。","可怜当日堆钱屋，寂寂无人晚照中。"]},{"t":"过二圣王氏故居感战死者","f":"七言绝句","c":["数仞墙围石作基，几年风雨长苔衣。","英雄地迫难为计，血汗游魂不得归。"]},{"t":"东山道中","f":"七言绝句","c":["采遍山城草木芽，百年老树尽枯槎。","眼前多少闲田地，雨后春耕有几家。"]},{"t":"掷笔台","f":"七言绝句","c":["空山老却涅槃师，掷笔台前旦过稀。","雉子岂知身后事，至今犹傍法堂飞。"]},{"t":"太平泉 其一","f":"七言绝句","c":["试从涧底觅根源，剔藓剜苔得旧泉。","人事尽随流水去，几时复见太平年。"]},{"t":"太平泉 其二","f":"七言绝句","c":["水边堪赋濯缨歌，来往游人分外多。","为问太平何处是，等闲不识起风波。"]},{"t":"子荣过家上冢 其一","f":"七言绝句","c":["班超万里归无期，张翰虽归如不归。","君看昼锦堂中相，十五年前一布衣。"]},{"t":"子荣过家上冢 其二","f":"七言绝句","c":["名遂功成不肯闲，故乡曾见几人还。","百年扶杖华颠老，争看钱家锦绣山。"]},{"t":"十七日送行","f":"七言绝句","c":["悤悤又别故园春，花落犹随马后尘。","相对离筵莫惆怅，送行人是欲行人。"]},{"t":"勉和筹堂来韵 其一","f":"七言绝句","c":["往古来今秋复春，嬴颠刘蹶总成尘。","蜗牛角上争闲气，笑倒南华梦蝶人。"]},{"t":"勉和筹堂来韵 其二","f":"七言绝句","c":["气似阳和处处春，但随流俗混光尘。","须知舌在为身累，非是是非何等人。"]},{"t":"勉和筹堂来韵 其三","f":"七言绝句","c":["四海男儿得志时，归来一段话新奇。","野人不管兴亡事，饮恨闲看老杜诗。"]},{"t":"勉和筹堂来韵 其四","f":"七言绝句","c":["汉祖龙兴自有时，未应六出计皆奇。","采芝人向山中老，不见功名一首诗。"]},{"t":"送颍阳史正之之邓州","f":"七言绝句","c":["风俗相邻鴃舌蛮，杖藜南去早宜还。","年今已近强而仕，捷径休离少室山。"]},{"t":"赠陈仲和","f":"七言绝句","c":["百年浮世落花风，漆水荣华一梦空。","拈起数珠都忘却，大千沙界入圆融。"]},{"t":"和秦彦容韵","f":"七言绝句","c":["花信风传阆苑香，腾空鹤驾望仙郎。","当年谁为看炉鼎，曾得丹砂入药囊。"]},{"t":"碧落途中遇雪","f":"七言绝句","c":["出郭山行十里馀，据鞍拥鼻一臞儒。","飞花落在吟肩上，便是蓝关遇雪图。"]},{"t":"大阳值雪","f":"七言绝句","c":["埽地阴云拨不开，北风吹落豆楷灰。","相逢父老应相笑，直待山头白后来。"]},{"t":"呈济之","f":"七言绝句","c":["朝醒暮醉几时休，鸡黍人家见客留。","闻道曲生行处有，西村明日趁扶头。"]},{"t":"留别","f":"七言绝句","c":["故人不寄一枝梅，亲到前村雪里来。","兴未尽时还又去，为君更觅暖寒杯。"]},{"t":"留别草堂诸友","f":"七言绝句","c":["青山莫厌往来频，野鹤孤云自在身。","客路傍春风色好，明朝便是远行人。"]},{"t":"和筹堂送别韵 其一","f":"七言绝句","c":["山城望断首重回，犹劝春风马上杯。","有似卫轩当日鹤，羽毛养就却归来。"]},{"t":"和筹堂送别韵 其二","f":"七言绝句","c":["白发相逢得几回，离亭苦劝送行杯。","元龙不识求田意，徒使青山笑往来。"]},{"t":"和河上送行韵","f":"七言绝句","c":["沁南幕客尽诗豪，斧月斤云得句高。","吏部文章笑东野，若为自比倚松蒿。"]},{"t":"蚁战图 其一","f":"七言绝句","c":["声势何劳斗似牛，看看一雨到山头。","大家不肯勤王去，只待槐宫坏即休。"]},{"t":"蚁战图 其二","f":"七言绝句","c":["胶胶扰扰战争多，岁月循环得几何。","树下老人观物化，梦魂应不到南柯。"]},{"t":"画鹤","f":"七言绝句","c":["两翅如轮骨己仙，昂昂只合在林泉。","且休相逐乘轩去，自有人谋二顷田。"]},{"t":"海棠露","f":"七言绝句","c":["轻风袅袅泛崇光，长恨司花不与香。","春睡一声莺唤起，却教老眼见啼妆。"]},{"t":"张氏肯堂","f":"七言绝句","c":["百年兰玉水边村，万轴牙签席上珍。","同队鱼中见头角，一朝富贵异于人。"]},{"t":"孟浩然图 其一","f":"七言绝句","c":["却因明主放还山，破帽骑驴骨相寒。","诗句眼前吟不尽，北风吹雪满长安。"]},{"t":"孟浩然图 其二","f":"七言绝句","c":["蹇驴却指旧山归，可笑先生五字诗。","仕为不求明主弃，此行安得怨王维。"]},{"t":"上陶固岭","f":"七言绝句","c":["悤悤出郭晓风寒，一片云收爽气山。","上尽坡陀试回首，人家住在翠微閒。"]},{"t":"野菊","f":"七言绝句","c":["风露丛中取次芳，愁边过却几重阳。","秋光到处多无主，不是闲花不肯香。"]},{"t":"席次","f":"七言绝句","c":["不到西山二十春，风光别后一番新。","再三点检尊前客，白发相看有几人。"]},{"t":"驴为人盗去 其一","f":"七言绝句","c":["磨嫌居士谋生拙，碑恨诗人下道看。","好在隔花临水处，为谁信辔逐金鞍。"]},{"t":"驴为人盗去 其二","f":"七言绝句","c":["长街愁杀郑昌图，便是徒行鲁大夫。","纵复东家借还许，不知泥滑敢骑无。"]},{"t":"渊明归来图","f":"七言绝句","c":["一旦仓惶马后牛，衣冠从此折腰羞。","先生不是归来早，束带人前几督邮。"]},{"t":"席上戏李巽之","f":"七言绝句","c":["薰风原上麦连云，箫鼓家家乐社神。","半醉尊前喧语笑，老夫愁独泪沾巾。"]},{"t":"和史邦直桥上韵","f":"七言绝句","c":["规模杜预见成功，横截长流跨彩虹。","亭长莫邀来往客，须防中有夺牛公。"]},{"t":"过龙门","f":"七言绝句","c":["流水潺潺漱石根，又还怀古过龙门。","行人但礼龛中像，谁识当年禹作痕。"]},{"t":"夜梦月下与数仙子酌酒仍各赋诗","f":"七言绝句","c":["天风一埽暮云开，收拾群仙共酒杯。","但指今宵是新月，不知曾照古人来。"]},{"t":"七夕","f":"七言绝句","c":["云汉双星聚散频，一年一度事还新。","民閒送巧浑闲事，不见长生殿里人。"]},{"t":"侄谦甫任长安回 其一","f":"七言绝句","c":["归去连昌忆旧游，长安回望使人愁。","只誇杨氏锦绣谷，曾上李家花萼楼。"]},{"t":"侄谦甫任长安回 其二","f":"七言绝句","c":["枝连叶附本同气，骨亲肉疏今几家。","但留济叔易一卷，与送蒋兄麻两车。"]},{"t":"母师圣醉归夜溺伊河抱桥柱而死","f":"七言绝句","c":["日日贪杯醉不醒，待将风味学刘伶。","可怜王子龛前水，夜半寒光落酒星。"]},{"t":"和张文玘 其一","f":"七言绝句","c":["景物秋来件件佳，江山都助与诗家。","我怜五鬼俱难送，先为文穷结柳车。"]},{"t":"和张文玘 其二","f":"七言绝句","c":["白发诗人喜诞誇，词源倾倒少陵家。","问君读后书多少，得满当年惠子车。"]},{"t":"和张文玘 其三","f":"七言绝句","c":["书生幢下布衣多，尽是嘲风咏月家。","若使乌台不弹后，看看欲载十牛车。"]},{"t":"和张文玘 其四","f":"七言绝句","c":["数閒茆舍老生涯，篱落相依四五家。","不见近来门外辙，故人应驾肉轮车。"]},{"t":"和筹堂送迎偶得 其一","f":"七言绝句","c":["怀抱秋来强自宽，相逢赖有旧青山。","郊原雨后堪图画，句引诗人兴不闲。"]},{"t":"和筹堂送迎偶得 其二","f":"七言绝句","c":["出门天地望中宽，马首浓迎著色山。","诗句满前无可道，恨今不复见闲闲。"]},{"t":"和筹堂送迎偶得 其三","f":"七言绝句","c":["画手从来说范宽，何如著眼看真山。","天公不欲山无主，分付筹堂好处闲。"]},{"t":"和筹堂送迎偶得 其四","f":"七言绝句","c":["诗愁谁道酒能宽，得句多于饭颗山。","莫使移文诮长往，工夫那取片时闲。"]},{"t":"和平太行路韵 其一","f":"七言绝句","c":["六丁驱役鬼神奔，一夜开山掌样平。","多少往来车马客，尚忧行路涩难行。"]},{"t":"和平太行路韵 其二","f":"七言绝句","c":["凿开险阻若天成，暂使时閒眼界平。","却羡长安西去路，青山不管送人行。"]},{"t":"和平太行路韵 其三","f":"七言绝句","c":["千年古道跨山城，可笑人心自不平。","容易莫将天险坏，须防闲客此闲行。"]},{"t":"和平太行路韵 其四","f":"七言绝句","c":["自古太行天下险，纵令禹凿不能平。","寻常著脚无安处，何况羊肠路上行。"]},{"t":"和君瑞月下闻砧","f":"七言绝句","c":["夜凉枕上梦频惊，有底秋天不肯明。","老眼近来闲泪少，那禁月下捣衣声。"]},{"t":"和筹堂述怀 其一","f":"七言绝句","c":["长恨周人咏黍离，不期亲到闵周时。","一朝小雅废将尽，何处如今更有诗。"]},{"t":"和筹堂述怀 其二","f":"七言绝句","c":["白头相见话存亡，可惜漫漫夜转长。","烦恼尽无安脚处，出门十步九羊肠。"]},{"t":"访德老 其一","f":"七言绝句","c":["夜投破戒远公家，醉墨成章点不加。","堪笑颍师无手段，听琴人似听琵琶。"]},{"t":"访德老 其二","f":"七言绝句","c":["一朝不饮柰愁何，月下敲门载酒过。","佳句晓风杨柳岸，醉时吟了醒时哦。"]},{"t":"老杜醉归图","f":"七言绝句","c":["花下骑驴不踏泥，花閒醉后复何之。","慇勤骥子扶归去，明日重来别有诗。"]},{"t":"保汉公庙","f":"七言绝句","c":["仓惶刘氏未能安，跋扈将军力拔山。","若使楚人如却子，肯教义士不生还。"]},{"t":"戏呈节使王子告","f":"七言绝句","c":["唤取佳人舞绣筵，醉中往往爱逃禅。","我无红袖堪娱夜，翠被薰香独自眠。"]},{"t":"戏北台孙讲师仲远","f":"七言绝句","c":["何处闲田不可耕，山头烽火水边营。","道人高卧云千顷，留取南台与鹤鸣。"]},{"t":"元夜与泰禅洛阳观灯","f":"七言绝句","c":["行歌声里落梅风，烁烁华灯万盏红。","何似吾师方寸地，一轮明月小参中。"]},{"t":"历阳侯","f":"七言绝句","c":["韩生去世冠军废，独望楚强心亦劳。","谩向鸿门撞玉斗，岂知鹿死在金刀。"]},{"t":"郦食其","f":"七言绝句","c":["多少中原逐鹿人，独凭片舌下齐城。","淮阴不喜书生事，能免他年猎犬烹。"]},{"t":"四皓奕棋图","f":"七言绝句","c":["坐看咸阳王气收，岂无人杰自安刘。","都缘鸿鹄心犹在，一局闲棋不到头。"]},{"t":"魏徵","f":"七言绝句","c":["立朝谠议尽良规，谁使君王死后疑。","一旦銮舆渡辽水，即时扶起墓前碑。"]},{"t":"王季文南迈怏怏不得意书此以缓之","f":"七言绝句","c":["大家都待倚栏干，摘索幽花草棘閒。","方便春风无不到，忍教雪里一枝寒。"]},{"t":"代别呼延路钤","f":"七言绝句","c":["森森戈戟乱如麻，刚把毛锥傍史家。","弹铗去年门下客，白头今日又天涯。"]},{"t":"梅花堂小酌与河南府马师共","f":"七言绝句","c":["往来不绝郑崇门，清浊那分北海尊。","今夜梅花堂上月，与人作个好黄昏。"]},{"t":"过济源","f":"七言绝句","c":["几年不到竹梅閒，天际归来两鬓斑。","一片白云风埽尽，双明喜见旧青山。"]},{"t":"壬寅九日和君玉来韵 其一","f":"七言绝句","c":["山城与客醉陶然，日日相陪费万钱。","马上行人几时去，一杯我欲助离筵。"]},{"t":"壬寅九日和君玉来韵 其二","f":"七言绝句","c":["书生纸里亦枵然，欲去街头恰百钱。","寄语西风莫相笑，一杯便是菊花筵。"]},{"t":"和段正卿韵 其一","f":"七言绝句","c":["悠然相对酒杯闲，忽有新诗落坐閒。","唤起东篱无限兴，黄花须待与君看。"]},{"t":"和段正卿韵 其二","f":"七言绝句","c":["百计寻闲不得闲，功夫那取片时閒。","谁知九日龙山客，却被秋光冷眼看。"]},{"t":"秋日有感","f":"七言绝句","c":["节气先凋一叶桐，人閒何处不秋风。","梁园胜事随流水，满目愁云锁故宫。"]},{"t":"贾佐之以进士充军被挞","f":"七言绝句","c":["便从宁越立威名，可信王尼长作兵。","著甚不谈军旅事，碧油幢下尽书生。"]},{"t":"孤村","f":"七言绝句","c":["舍南舍北地多荒，三两□□□□□。","□士尽归箕欲手，未应医得眼前疮。"]},{"t":"解嘲","f":"七言绝句","c":["尊前共醉泼醅香，下马谁家白面郎。","见说千金能买笑，老夫那得一钱囊。"]},{"t":"王德华默轩","f":"七言绝句","c":["春秋岂敢措一字，宾主不须谈两都。","万事尽皆皮里著，为君终日鼓咙胡。"]},{"t":"对棋","f":"七言绝句","c":["到头不可托安危，那用搜寻局上机。","纵出吴宫阵图外，阴山未免嫁明妃。"]},{"t":"送苗世显归上党","f":"七言绝句","c":["故人千里寄书来，长恨天涯唤不回。","行路难行涩如棘，归装莫待北风催。"]},{"t":"跋鲁直帖","f":"七言绝句","c":["鸡毛不择三钱笔，虿尾挥成一幅书。","莫使观江神会得，因风夺去锦囊虚。"]},{"t":"许道真醉吟图","f":"七言绝句","c":["断蓬踪迹寄天涯，老去情钟恋物华。","回首锦江春寂寞，一杯愁里赋梨花。"]},{"t":"探官","f":"七言绝句","c":["版图填写百官志，楮券类排千字文。","堪笑吾儒多伎俩，一时鬻爵僣吾君。"]},{"t":"跋冯应之许司谏豉羊帖","f":"七言绝句","c":["还思写论付官奴，想见临池兴有馀。","莫把家鸡等闲厌，恐教人笑换羊书。"]},{"t":"王庭秀悠然轩","f":"七言绝句","c":["小轩开后快双明，峭拔南山立翠屏。","好是晚来新雨过，白云堆里露尖青。"]},{"t":"同申元帅游司马山","f":"七言绝句","c":["千年古庙映崇冈，寂寂空庭草树荒。","见说旱时求得雨，一池由有老龙藏。"]},{"t":"留别","f":"七言绝句","c":["主人把酒再三留，送客风高势未休。","更听愁眉歌一曲，尊前肠断小温柔。"]},{"t":"寒食戏书","f":"七言绝句","c":["蓦见花閒弄药回，同心髻绾绿云堆。","多情更有墙东月，送得秋千影过来。"]},{"t":"戏杨成之","f":"七言绝句","c":["客路风霜颇倦游，出门又是一番愁。","行人立马无情甚，扶上征鞍不自由。"]},{"t":"李晋王坟","f":"七言绝句","c":["雄名凛凛振沙陀，为国功深柰老何。","多少三垂冈上恨，伶人都进百年歌。"]},{"t":"游沁园","f":"七言绝句","c":["多少庭台堕劫灰，胜游踪迹几残碑。","风流人物今谁在，水绿山青似旧时。"]},{"t":"申元帅四隐图 其一 严子陵","f":"七言绝句","c":["羊裘隐迹唤难回，曾犯当年帝座来。","京洛江湖各天性，钓鱼台不羡云台。"]},{"t":"申元帅四隐图 其二 陶渊明","f":"七言绝句","c":["迎门儿女笑牵衣，回首人閒万事非。","自是田园有真乐，督邮那解遣君归。"]},{"t":"申元帅四隐图 其三 孟浩然","f":"七言绝句","c":["平生只有在山缘，北阙归来也自贤。","破帽蹇驴风雪里，新诗句句总堪传。"]},{"t":"申元帅四隐图 其四 李太白","f":"七言绝句","c":["谪在人閒凡几年，诗中豪杰酒中仙。","不因采石江头月，那得骑鲸去上天。"]},{"t":"大颠图 其一","f":"七言绝句","c":["星斗文章世所传，狂澜回在禹功前。","先生不踏潮阳路，震旦花开几大颠。"]},{"t":"大颠图 其二","f":"七言绝句","c":["一夕投荒万里行，增光日月更谁能。","相逢尽说空门话，多少人閒有发僧。"]},{"t":"三害图 其一","f":"七言绝句","c":["慷慨平西气不衰，勇于三害欲除时。","流芳已入忠臣传，何处人閒更有诗。"]},{"t":"三害图 其二","f":"七言绝句","c":["挟矢操弓短后衣，扬扬意气似男儿。","欲凭一怒除民害，可惜为人自不知。"]},{"t":"平水八咏 其一 陶唐春色","f":"七言绝句","c":["松柏森森护帝宫，至今和气在河东。","诗人不尽当时事，八景图中见国风。"]},{"t":"平水八咏 其二 广胜晴岚","f":"七言绝句","c":["等闲过了万千峰，偃蹇相看意不浓。","洗出青山真面目，祗疑海底有天龙。"]},{"t":"平水八咏 其三 平湖飞絮","f":"七言绝句","c":["三月湖边祓禊亭，依依杨柳雨中青。","晚来风起花如雪，春色都归水上萍。"]},{"t":"平水八咏 其四 锦滩落花","f":"七言绝句","c":["春风桃叶复桃根，相妒封姨似少恩。","无限乱红随水去，人閒何处觅仙源。"]},{"t":"平水八咏 其五 汾水孤帆","f":"七言绝句","c":["古渡无人鸟迹多，眼前历历旧山河。","片帆不是秋风客，谁向中流发棹歌。"]},{"t":"平水八咏 其六 姑山晚照","f":"七言绝句","c":["嫩寒篱落似江村，雪里精神月下魂。","桥北桥南路分处，行人立马待黄昏。"]},{"t":"平水八咏 其七 晋桥梅月","f":"七言绝句","c":["物外神仙自一家，等闲不许占烟霞。","只今冰雪人何处，惆怅山前日易斜。"]},{"t":"平水八咏 其八 西蓝夜雨","f":"七言绝句","c":["暮云深锁梵王家，楼阁峥嵘阅岁华。","香火半残僧入定，卧听窗外落檐花。"]},{"t":"锦堂四咏 其一 春水满四泽","f":"七言绝句","c":["一番雨过绿生肥，正是桃花欲浪时。","掠地风来吹不皱，细看面面尽玻璃。"]},{"t":"锦堂四咏 其二 夏云多奇峰","f":"七言绝句","c":["初见云从山里出，须臾云结势如山。","一声霹雳催时雨，云不能闲山自闲。"]},{"t":"锦堂四咏 其三 秋月扬明辉","f":"七言绝句","c":["谁为天公洗眸子，试将把酒问姮娥。","清光一片已如许，斫却桂时应更多。"]},{"t":"锦堂四咏 其四 冬岭秀孤松","f":"七言绝句","c":["凛凛苍髯晚节孤，雪中倾盖若旁无。","一经元亮盘桓后，气压秦时五大夫。"]},{"t":"沁园十二咏 其一 熙熙堂","f":"七言绝句","c":["眼前草木强争春，往日繁华一聚尘。","山水中閒赏心在，不知谁是肯堂人。"]},{"t":"沁园十二咏 其二 翠兰亭","f":"七言绝句","c":["蓬艾丛深特地藏，游蜂何处觅幽芳。","楚人大段无分别，不识离骚传里香。"]},{"t":"沁园十二咏 其三 暗香亭","f":"七言绝句","c":["三两横斜鹤膝枝，一朝须有返魂时。","试看今后黄昏月，得似西湖七字诗。"]},{"t":"沁园十二咏 其四 七贤台","f":"七言绝句","c":["放迹山阳志尚同，至今林下仰高风。","欲将人物图中看，恐遇生前李卫公。"]},{"t":"沁园十二咏 其五 漱玉池","f":"七言绝句","c":["古人观水必观澜，一滴涓流一滴寒。","放取黄陂千万顷，莫教龙口吐吞难。"]},{"t":"沁园十二咏 其六 江源亭","f":"七言绝句","c":["羽觞到处不容停，争看中流落酒星。","彼此一时修禊事，未应人物愧兰亭。"]},{"t":"沁园十二咏 其七 屏俗庵","f":"七言绝句","c":["世上无人可立谈，眼前只有此君堪。","当年借得谁家宅，疑是今来屏俗庵。"]},{"t":"沁园十二咏 其八 清晖亭","f":"七言绝句","c":["高山森似剑铓立，流水平如罗带舒。","人在水光山色里，笑渠潘阆倒骑驴。"]},{"t":"沁园十二咏 其九 富览亭","f":"七言绝句","c":["天于万物岂私我，领略风光天不嗔。","自古山阳景佳处，尽都分付与闲人。"]},{"t":"沁园十二咏 其十 桃园","f":"七言绝句","c":["一时得意笑春风，不见春风满树空。","老去惜花心尚在，为君留眼看蒸红。"]},{"t":"沁园十二咏 其十一 意在亭","f":"七言绝句","c":["绿水古今流不尽，好山前后势相连。","适来荷蒉者谁子，应笑有心哉此贤。"]},{"t":"沁园十二咏 其十二 涌珠泉","f":"七言绝句","c":["渊底睡龙徒有颔，沙中老蚌恐无胎。","疾雷惊裂苍苔地，迸出鲛人泪颗来。"]},{"t":"碧落四景 其一 横峰卧云","f":"七言绝句","c":["蛰龙起后愿相从，便有人閒润物功。","一片青山是归处，无心更逐渡溪风。"]},{"t":"碧落四景 其二 阴壑积雪","f":"七言绝句","c":["漠漠山阴雪拥门，何时天道变寒暄。","虽然不是回光地，销得阳和几许恩。"]},{"t":"碧落四景 其三 寒泉漱玉","f":"七言绝句","c":["沥沥山泉枕畔鸣，六根先得一根清。","从来只向琴中听，不识徽弦意外声。"]},{"t":"碧落四景 其四 枯松挂月","f":"七言绝句","c":["门前老树数难推，独有栽松道者知。","夜半风催山月上，政当鹤睡觉来时。"]},{"t":"周昉内人图 其一 吹笙","f":"七言绝句","c":["旧曲闻来似敛眉，料应只恨赏音迟。","梨园传得新翻谱，著意参差竹里吹。"]},{"t":"周昉内人图 其二 汲泉","f":"七言绝句","c":["非关古井不波澜，祗恨银瓶一掬悭。","欲助长流御沟水，再教红叶到人閒。"]},{"t":"周昉内人图 其三 倦绣","f":"七言绝句","c":["心情犹在未收时，却顾花閒影渐移。","不道春来添几线，日长只与睡相宜。"]},{"t":"周昉内人图 其四 捣衣","f":"七言绝句","c":["一夕秋风雁过声，铁衣辛苦向边城。","将军不用和戎计，双杵休辞月下鸣。"]},{"t":"周昉内人图 其五 剪爪","f":"七言绝句","c":["袖里纤纤只合存，如何春笋不嫌髡。","金钗坠后无因见，藏得开元一捻痕。"]},{"t":"周昉内人图 其六 弹琴","f":"七言绝句","c":["休言三尺是枯桐，大抵声音与政通。","曾得王君意中事，便从弦上和薰风。"]},{"t":"周昉内人图 其七 学书","f":"七言绝句","c":["数幅云笺自卷舒，试教落笔看何如。","休将彤管题闲句，正要班姬续汉书。"]},{"t":"周昉内人图 其八 按乐","f":"七言绝句","c":["倚风无力见温柔，初下喧天羯鼓楼。","犹向花阴理新曲，君王不惜锦缠头。"]},{"t":"周昉内人图 其九 览镜","f":"七言绝句","c":["不教朱粉污天真，长对菱花顾影频。","但把蛾眉埽来淡，尚嫌不似虢夫人。"]},{"t":"襄阳咏史 其一 古堤","f":"七言绝句","c":["一决江源水自东，长堤隐隐卧如虹。","不因传得襄阳操，人世何由见禹功。"]},{"t":"襄阳咏史 其二 白沙湖","f":"七言绝句","c":["闻道沙堤水陷时，茫茫无处觅完堤。","当时禹迹依然在，以壑为邻笑白圭。"]},{"t":"襄阳咏史 其三 戍逻垦田","f":"七言绝句","c":["屯彻南阳井井田，剑牛刀犊两功全。","石城惊落吴儿胆，野宿貔貅万灶烟。"]},{"t":"襄阳咏史 其四 樊城","f":"七言绝句","c":["暂来朱序秦还守，初入曹仁汉复攻。","颠倒江山今几主，樊侯依旧袭周封。"]},{"t":"襄阳咏史 其五 汉高庙","f":"七言绝句","c":["垓下未闻歌散楚，泽中已见哭亡秦。","乾坤到底归真主，愁杀鸿门碎斗人。"]},{"t":"襄阳咏史 其六 光武庙","f":"七言绝句","c":["海内英雄待一呼，云龙际会入东都。","羯奴不识真人事，徼倖中原欲并驱。"]},{"t":"襄阳咏史 其七 楚昭王庙","f":"七言绝句","c":["一閒茅屋暗尘埃，香火凄凉几奠杯。","故国到今如传舍，后人复使后人哀。"]},{"t":"襄阳咏史 其八 宋玉宅","f":"七言绝句","c":["离骚经里见文章，水绿山青是楚乡。","往事一场巫峡梦，秋风摇落在东墙。"]},{"t":"襄阳咏史 其九 保汉公庙","f":"七言绝句","c":["将将提兵气自扬，一朝翻为沐猴忙。","得从虎口抽身去，不必雷霆怒假王。"]},{"t":"襄阳咏史 其十 酂城","f":"七言绝句","c":["谁是兴刘第一功，我侯只合最先封。","当时猎犬犹争甚，得鹿权都在指踪。"]},{"t":"襄阳咏史 其十一 三顾门","f":"七言绝句","c":["将军命驾出门西，想见门从向日题。","山下卧龙谁说破，赏音元直在檀溪。"]},{"t":"襄阳咏史 其十二 隆中","f":"七言绝句","c":["一朝师出震关东，料敌曹吴几日功。","未毕将军天下计，乾坤容易老英雄。"]},{"t":"襄阳咏史 其十三 关将军庙","f":"七言绝句","c":["鼎足相吞势未分，谁能倾盖得将军。","曹吴不是中原手，天下英雄有使君。"]},{"t":"襄阳咏史 其十四 鹿门山","f":"七言绝句","c":["百年巢穴子孙安，十日长闻九日闲。","说破姓名人不识，鹿门山是德公山。"]},{"t":"襄阳咏史 其十五 庞士元宅","f":"七言绝句","c":["鹰自养来饥肯去，龙从卧后顾须频。","到头骥足非难展，祇在当时驾驭人。"]},{"t":"襄阳咏史 其十六 徐庶宅","f":"七言绝句","c":["谁知方寸去留初，尽把功名付葛庐。","举目檀溪人不见，空传谷隐念交书。"]},{"t":"襄阳咏史 其十七 刘表祠","f":"七言绝句","c":["天运端能卧可收，江山形势数荆州。","当时若听韩嵩策，那得曹瞒享士牛。"]},{"t":"襄阳咏史 其十八 谷隐山","f":"七言绝句","c":["衮斧留心汉晋閒，岂期谷隐避名难。","一人有半随秦去，不得相离释道安。"]},{"t":"襄阳咏史 其十九 庞公祠","f":"七言绝句","c":["踏破衡山急急回，凤林尽是漉篱材。","大家了得无生著，倾出团圞话里来。"]},{"t":"襄阳咏史 其二十 凤林","f":"七言绝句","c":["天宝诗人去却回，果曾北阙上书来。","若为耆旧无新语，明主何尝弃不才。"]},{"t":"襄阳咏史 其二十一 斩蛟渚","f":"七言绝句","c":["久愤江于投水俗，近忧泉室泣珠人。","到头不是池中物，血溅惊波剑有神。"]},{"t":"襄阳咏史 其二十二 夫人城","f":"七言绝句","c":["见说韩门素识兵，故知西北势先倾。","未应有子如豚犬，何在夫人自筑城。"]},{"t":"襄阳咏史 其二十三 诫虎碑","f":"七言绝句","c":["未除不必烦周处，欲刺何须待卞庄。","入市如羊听命去，至今无害到襄阳。"]},{"t":"襄阳咏史 其二十四 杜甫故里","f":"七言绝句","c":["不知故隐几时离，天宝年閒处处诗。","过客不须寻世谱，万山山下看沈碑。"]},{"t":"襄阳咏史 其二十五 尹氏一门四阙","f":"七言绝句","c":["萱堂犹是忘忧地，乌屋相传反哺恩。","一段家风谁出自，千年鼻祖守关门。"]},{"t":"襄阳咏史 其二十六 武安君庙","f":"七言绝句","c":["归去咸阳是老头，如何此地肯重游。","分明祀典无交涉，只合英灵在杜邮。"]},{"t":"襄阳咏史 其二十七 修禊亭","f":"七言绝句","c":["相唤相呼上巳游，国人无日不思周。","近来烽火遭三月，那得闲杯逐水流。"]},{"t":"襄阳咏史 其二十八 汉阴台","f":"七言绝句","c":["怪来赐也多言甚，笑倒忘机老汉阴。","巧拙大都归一溉，宁教劳力莫劳心。"]},{"t":"襄阳咏史 其二十九 善谑驿","f":"七言绝句","c":["皆因盂酒与豚蹄，致使他乡笑滑稽。","无限驿亭来往客，独言齐赘不归齐。"]},{"t":"襄阳咏史 其三十 沧浪歌","f":"七言绝句","c":["江上扬扬一棹波，众中清浊笑怀沙。","不知歌后沧浪曲，却入骚人屈宋衙。"]},{"t":"襄阳咏史 其三十一 竞渡","f":"七言绝句","c":["憔悴沉湘楚大夫，魂招鱼腹肯来无。","至今江上渔歌在，尚问何由得渡湖。"]},{"t":"襄阳咏史 其三十二 抱玉岩","f":"七言绝句","c":["特特来从抵鹊山，一心都在献芹閒。","非关楚国真难辨，举世人皆厌等闲。"]},{"t":"襄阳咏史 其三十三 习家池","f":"七言绝句","c":["日日山公载酒过，醒时常少醉时多。","儿童拍手阑街笑，惊破沧浪一曲歌。"]},{"t":"襄阳咏史 其三十四 的颅溪","f":"七言绝句","c":["得雨蛟龙未易图，枉劳木禺用机谟。","死生毕竟谁堪托，今日才方见的颅。"]},{"t":"襄阳咏史 其三十五 作乐山","f":"七言绝句","c":["悠悠曾不倦登临，眼底何人为赏音。","白雪一歌犹掩耳，安知梁父是龙吟。"]},{"t":"襄阳咏史 其三十六 冠盖里","f":"七言绝句","c":["道口亭前多贵游，一时来往亦风流。","若能共画安刘计，岂独英雄记里收。"]},{"t":"襄阳咏史 其三十七 呼鹰台","f":"七言绝句","c":["英豪并起望人才，底事将军谩筑台。","倘使曹公肉能饱，如何唤得野鹰来。"]},{"t":"襄阳咏史 其三十八 仲宣井","f":"七言绝句","c":["试看汲古几何深，犹有馀波慰渴心。","谁把石栏移便坐，并邻又得一繁钦。"]},{"t":"襄阳咏史 其三十九 兹楼","f":"七言绝句","c":["见说襄阳有古风，可怜耆旧老无功。","当年汉主龙兴地，尽在登楼四望中。"]},{"t":"襄阳咏史 其四十 堕泪碑","f":"七言绝句","c":["愤深藉馆年年祭，痛切夷陵岁岁祠。","不见征南遗爱地，至今泪堕岘山碑。"]},{"t":"襄阳咏史 其四十一 沈碑","f":"七言绝句","c":["中原人物老书生，塞破乾坤万古名。","俗子不知碑尚在，一朝南渡愧荒伧。"]},{"t":"襄阳咏史 其四十二 晋柏","f":"七言绝句","c":["亭亭霜干上参天，色黛皮苍老更坚。","当日不知谁手植，到今人与树千年。"]},{"t":"襄阳咏史 其四十三 文选楼","f":"七言绝句","c":["朝朝暮暮蠹书鱼，选尽人閒得意书。","常恐不能精此理，祗缘老杜近楼居。"]},{"t":"襄阳咏史 其四十四 解佩渚","f":"七言绝句","c":["相遇江皋事颇奇，一双佩解去还遗。","未能南国无游女，咏取周人汉广诗。"]},{"t":"襄阳咏史 其四十五 弄珠滩","f":"七言绝句","c":["江沙一日蚌胎虚，游女争誇掌上珠。","美化不将风俗禁，他年恐作媚川都。"]},{"t":"襄阳咏史 其四十六 金沙泉","f":"七言绝句","c":["何处山泉味最佳，从来独说有金沙。","楚人遍地宜城酒，莫著淄渑诳易牙。"]},{"t":"襄阳咏史 其四十七 涌月亭","f":"七言绝句","c":["徘徊亭上晚相宜，月与高人本有期。","不比寻常三五夜，十分圆后是来时。"]},{"t":"集古 南游","f":"七言绝句","c":["一片归心白羽轻，一场春梦不分明。","东风二月淮阴郡，总是关山离别情。"]},{"t":"集古 自遣","f":"七言绝句","c":["南路蹉跎客未回，山桃野杏两三栽。","逢春渐觉飘蓬苦，更向花前把一杯。"]},{"t":"集古 雨后出郊","f":"七言绝句","c":["柳塘烟起日西斜，马踏春泥半是花。","何处最伤游客思，绿阴相閒两三家。"]},{"t":"集古 寒食","f":"七言绝句","c":["闲身行止属年华，故国春归未有涯。","一树梨花一溪月，不知墙外是谁家。"]},{"t":"集古 寒食席次","f":"七言绝句","c":["鞦韆打困解罗裙，把酒相看日又曛。","处士不知巫峡梦，春来犹见伴行云。"]},{"t":"集古 郭外","f":"七言绝句","c":["寒食悲看郭外春，数声鸦噪日将曛。","山中旧宅无人住，一树繁花傍古坟。"]},{"t":"集古 小桃","f":"七言绝句","c":["桃花依旧笑春风，怅望无人此醉同。","应是梦中飞作蝶，树头树底觅残红。"]},{"t":"集古 看花","f":"七言绝句","c":["两岸山花似雪开，开时莫放艳阳回。","明朝携酒犹堪赏，雨涨春流隔往来。"]},{"t":"集古 感花","f":"七言绝句","c":["无人不道看花回，犹忆红螺一两杯。","曾是管弦同醉伴，来时欢笑去时哀。"]},{"t":"集古 其一 惜花","f":"七言绝句","c":["花树流莺日过迟，少年争惜最红枝。","何人尽得天生态，为报东风且莫吹。"]},{"t":"集古 其二 惜花","f":"七言绝句","c":["绣轭香鞯夜不归，看花只恐看来迟。","今朝几许风吹落，多在青苔少在枝。"]},{"t":"集古 暮春","f":"七言绝句","c":["一年春色负归期，绿叶成阴子满枝。","公子王孙莫来好，如今不似洛阳时。"]},{"t":"集古 其一 送春","f":"七言绝句","c":["可怜寥落送春心，负郭依山一径深。","燕子不归花著雨，小溪犹忆去年寻。"]},{"t":"集古 其二 送春","f":"七言绝句","c":["二月已破三月来，常嗟物候暗相催。","几时心绪浑无事，终日传杯不放杯。"]},{"t":"集古 遗兴","f":"七言绝句","c":["读彻闲书弄水回，绿杨移傍小庭栽。","闭门尽日无人到，便有春光四面来。"]},{"t":"集古 下楼","f":"七言绝句","c":["绣帘珠户未曾开，却向春风领恨回。","行到中庭数花朵，遥闻语笑自空来。"]},{"t":"集古 招饮","f":"七言绝句","c":["当时朝士已无多，故里心期柰别何。","不用凭栏苦回首，且来花里听笙歌。"]},{"t":"集古 春感","f":"七言绝句","c":["岁岁无如老去何，东城南陌强经过。","不知谁唱归春曲，断得人肠不在多。"]},{"t":"集古 春怨","f":"七言绝句","c":["已恨东风不展眉，落花惆怅满尘衣。","与君试向江边觅，嬴得悽凉索漠归。"]},{"t":"集古 约同归","f":"七言绝句","c":["故国烟花想已残，浮生各自系悲欢。","青山一道同云雨，步步相携不觉难。"]},{"t":"集古 江村","f":"七言绝句","c":["夜添山雨作江声，绿暗红藏江上村。","何处人閒似仙境，寥寥一犬吠桃源。"]},{"t":"集古 送客之江陵","f":"七言绝句","c":["独上江楼思渺然，故人去后绝朱弦。","西南一望和云水，入郭登桥出郭船。"]},{"t":"集古 其一 赠别","f":"七言绝句","c":["萧萧落叶送残秋，楼上黄昏欲望休。","满目暮云风捲尽，亭亭孤月照行舟。"]},{"t":"集古 其二 赠别","f":"七言绝句","c":["洞庭风软荻花秋，客散江亭雨未休。","南去北来人自老，此中离恨两难收。"]},{"t":"集古 秋怀","f":"七言绝句","c":["八月霜飞柳遍黄，鸟鸣山馆客思乡。","十年马足知多少，地角天涯不是长。"]},{"t":"集古 洛中","f":"七言绝句","c":["洛阳犹自有残春，水北原南草色新。","山酒一卮歌一曲，不能回避看花尘。"]},{"t":"集古 洛中感旧","f":"七言绝句","c":["千里江山一梦回，悔缘名利入尘埃。","年光到处皆堪赏，谁与愁眉唱一杯。"]},{"t":"集古 席上","f":"七言绝句","c":["春风寂寞旆旌回，两度天涯地角来。","重到笙歌分散地，与人头上拂尘埃。"]},{"t":"集古 忆昔","f":"七言绝句","c":["忆昔争游曲水滨，当轩下马入锦茵。","如今不似时平日，风起杨花愁杀人。"]},{"t":"集古 送客之荆南","f":"七言绝句","c":["千山红树万山云，山鸟江枫得雨新。","我自飘零是羁旅，不堪仍送故乡人。"]},{"t":"集古 南征","f":"七言绝句","c":["两行旌旆接扬州，烽火城西百尺楼。","九姓如今尽臣妾，青天犹列旧旄头。"]},{"t":"集古 其一 老将","f":"七言绝句","c":["蓬根吹断雁南翔，晓鼓钟中两鬓霜。","独倚关亭还把酒，不堪秋气入金疮。"]},{"t":"集古 其二 老将","f":"七言绝句","c":["怜君一见一悲歌，破虏曾轻马伏波。","今日宝刀无杀气，太平功业在山河。"]},{"t":"集古 其三 老将","f":"七言绝句","c":["门前不改旧山河，泪落灯前一曲歌。","更把玉鞭云外指，只缘君处受恩多。"]},{"t":"集古 感征夫家","f":"七言绝句","c":["臂上彫弓百战勋，居延城外又移军。","不知万里沙场苦，犹自笙歌彻晓闻。"]},{"t":"集古 从军","f":"七言绝句","c":["万里还乡未到乡，受降城外月如霜。","谁家营里吹羌笛，不是愁人也断肠。"]},{"t":"集古 闻角","f":"七言绝句","c":["铁马狐裘出汉营，瘴云深处守孤城。","无端遇著场心事，鸣轧江楼角一声。"]},{"t":"集古 闻笛","f":"七言绝句","c":["山头烽火水边营，祇有牛羊与马群。","羌笛何须怨杨柳，忍教呜咽夜长闻。"]},{"t":"集古 汉女","f":"七言绝句","c":["大边物色更无春，碧玉芳年事冠军。","人世死前惟有别，阳台去作不归云。"]},{"t":"集古 有别","f":"七言绝句","c":["长对春风裛泪痕，殷红马上石榴裙。","无端更唱关山曲，哀怨教人不忍闻。"]},{"t":"集古 怨别","f":"七言绝句","c":["书来未报几时还，终日昏昏醉梦閒。","别易会难长自叹，不堪重过望夫山。"]},{"t":"集古 寄远","f":"七言绝句","c":["桃李年年上国新，单于鼓角隔山闻。","一行书信千行泪，不是思君是恨君。"]},{"t":"集古 其一 恨别","f":"七言绝句","c":["悽悽长是别离情，冰簟银床梦不成。","昨夜秋风今夜雨，篝灯愁泣到天明。"]},{"t":"集古 其二 恨别","f":"七言绝句","c":["君问归期未有期，迩来中酒起常迟。","山长水远无消息，指点庭花又过时。"]},{"t":"集古 其一 感旧","f":"七言绝句","c":["流莺惊起不成栖，入到繁华梦觉时。","人面只今何处在，魏公怀旧嫁文姬。"]},{"t":"集古 其二 感旧","f":"七言绝句","c":["碧栏干外绣帘垂，曾识云仙至小时。","见我佯羞频点影，满头犹自插花枝。"]},{"t":"集古 其三 感旧","f":"七言绝句","c":["九陌初晴处处春，日高深院断无人。","尊前花下长相见，宋玉东家是旧邻。"]},{"t":"集古 代送别","f":"七言绝句","c":["陇上流泉陇下分，目随征雁过寒云。","人生适意无南北，莫向阳台梦使君。"]},{"t":"集古 悼征妇","f":"七言绝句","c":["万里行人尚未还，百年多在别离閒。","当时惊觉高唐梦，为雨为云过别山。"]},{"t":"集古 春夜","f":"七言绝句","c":["春风二月落花时，忆得前年君寄诗。","共道人家惆怅事，向灯弯尽一双眉。"]},{"t":"集古 睡起","f":"七言绝句","c":["万转千回懒下床，不辞鶗鴂妒年芳。","酷怜一觉平明睡，枕破施朱隔宿妆。"]},{"t":"集古 无睡","f":"七言绝句","c":["江南江北望烟波，颦黛低红别怨多。","尽日伤心人不见，卧来无睡欲如何。"]},{"t":"集古 谩书","f":"七言绝句","c":["已共红尘迹渐疏，画檐愁见燕归初。","无端有寄闲消息，肠断萧娘一纸书。"]},{"t":"集古 其一 寄情","f":"七言绝句","c":["年光空感疾如流，同向春风各自愁。","有境牵怀人不会，落花深处指青楼。"]},{"t":"集古 其二 寄情","f":"七言绝句","c":["曾留宋玉旧衣裳，云雨巫山枉断肠。","不为傍人羞不起，夜来新惹桂枝香。"]},{"t":"集古 其三 寄情","f":"七言绝句","c":["寂寥满地落花红，独倚栏干花露中。","征客未来音信断，年年回首泣春风。"]},{"t":"集古 秋夜","f":"七言绝句","c":["掷却风光忆少年，多生信有短因缘。","欲知此恨无穷处，星落银河月半天。"]},{"t":"集古 有感","f":"七言绝句","c":["风轻帘幕燕争飞，到处烟花恨别离。","倚柱寻思倍惆怅，映人匀却泪胭脂。"]},{"t":"集古 戏荅","f":"七言绝句","c":["公子王孙逐后尘，近来方解惜青春。","春心不惬空归去，长伴吹萧别有人。"]},{"t":"集古 其一 戏遣","f":"七言绝句","c":["雨散云收一饷閒，不知何处入空山。","慇勤好取襄王意，下蔡城危莫破颜。"]},{"t":"集古 其二 戏遣","f":"七言绝句","c":["枉破阳城十万家，门前初下七香车。","自缘今日人心别，隔坐刚抛豆蔻花。"]},{"t":"集古 其一 偶见","f":"七言绝句","c":["莫愁还自有愁时，眉敛春山知为谁。","含泪向人羞不语，芙蓉头上绾青丝。"]},{"t":"集古 其二 偶见","f":"七言绝句","c":["满身花影倩人扶，清润潘郎玉不如。","毕竟多情何处好，庾楼明月堕云初。"]},{"t":"集古 其三 偶见","f":"七言绝句","c":["云髻朝来不欲梳，娉娉袅袅十三馀。","分明记得曾行处，看遍花枝尽不如。"]},{"t":"集古 听歌","f":"七言绝句","c":["清歌空得隔花闻，寂寞堂前日又曛。","共待夜深听一曲，女儿弦管弄参军。"]},{"t":"集古 寄怀","f":"七言绝句","c":["愁云漠漠草离离，去国还家一望时。","几度相思不相见，雪中梅下与谁期。"]},{"t":"集古 秋怨","f":"七言绝句","c":["且将团扇暂徘徊，泪滴闲阶长绿苔。","春色似怜歌舞地，不论时节遣花开。"]},{"t":"集古 悲故宫人","f":"七言绝句","c":["云惨烟愁苑路斜，宫莺衔出上阳花。","朱铅滴尽无心语，生死深恩不到家。"]},{"t":"集古 怀古","f":"七言绝句","c":["暮云宫阙古今情，芳草长含玉辇尘。","春意自知无主惜，落花犹似堕楼人。"]},{"t":"集古 旧游","f":"七言绝句","c":["山南山北雨濛濛，十载长安似梦中。","今日独来张乐地，故人坟树五秋风。"]},{"t":"集古 关中","f":"七言绝句","c":["岳北秋空渭北川，一村桑柘一村烟。","行人莫讶频回首，记得春深欲种田。"]},{"t":"集古 过梅溪旧居","f":"七言绝句","c":["远到音书转寂寥，青山隐隐水迢迢。","村园门巷多相似，花落梅溪雪未消。"]},{"t":"集古 登山阳郡楼","f":"七言绝句","c":["将军一去泣空营，槐柳萧疏绕郡城。","试上高楼望春色，落花流水叹浮生。"]},{"t":"集古 王公楼上会饮","f":"七言绝句","c":["诗酒能消一半春，紫微才调复知兵。","黄河九曲今归汉，独上高楼故国情。"]},{"t":"集古 送客之南宫","f":"七言绝句","c":["萧萧风竹夜窗寒，书剑催人不暂闲。","对酒已成千里客，断肠声里唱阳关。"]},{"t":"集古 荅筹堂","f":"七言绝句","c":["一夕秋风白发生，相思迢递隔重城。","前欢往恨分明在，嬴得青楼薄倖名。"]},{"t":"集古 夜集","f":"七言绝句","c":["金凤罗衣湿麝薰，装成掩泣欲行云。","傍人未必知心事，一曲狂歌酒百分。"]},{"t":"集古 戏书","f":"七言绝句","c":["春风何处有佳期，花满西园月满池。","料得也应怜宋玉，东邻墙短不曾窥。"]},{"t":"集古 重九","f":"七言绝句","c":["事去人亡迹自留，白云犹似汉时秋。","如今暂寄尊前笑，明日黄花蝶也愁。"]},{"t":"集古 十日遣兴","f":"七言绝句","c":["露叶如啼欲恨谁，晓庭空绕折残枝。","芳尊有酒无人共，卧看南山改旧诗。"]},{"t":"集古 古城","f":"七言绝句","c":["东风渐急夕阳斜，马上怀中尽落花。","肠断入城芳草路，孤烟起处是人家。"]},{"t":"集古 送行","f":"七言绝句","c":["天涯方叹异乡身，云别青山马踏尘。","欲问孤鸿向何处，依依还似北归人。"]},{"t":"集古 宫柳","f":"七言绝句","c":["寒食东风御柳斜，轻盈袅娜占年华。","试看三月春残后，不见人烟空见花。"]},{"t":"集古 对花","f":"七言绝句","c":["尽是刘郎去后栽，为谁零落为谁开。","风流才子多春思，半醉闲吟独自来。"]},{"t":"集古 宿横望","f":"七言绝句","c":["远上寒山石径斜，月临荒戍起啼鸦。","故乡今夜思千里，每到花时不在家。"]},{"t":"集古 妓为尼","f":"七言绝句","c":["无地无媒只一身，蛾眉画出月争新。","春来削发芙蓉寺，从此萧郎是路人。"]},{"t":"集古 新居","f":"七言绝句","c":["每忆云山养短才，蓬门今始为君开。","落花寂寂黄昏雨，依旧去年双燕来。"]},{"t":"集古 寒食野外","f":"七言绝句","c":["浮云飞尽日西颓，莫向花前泣酒杯。","独上郊原人不见，野风吹起纸钱灰。"]},{"t":"集古 赠别","f":"七言绝句","c":["绿柳才黄半未匀，灞桥攀折一何频。","相逢且莫推辞酒，明日忽为千里人。"]},{"t":"集古 柳","f":"七言绝句","c":["还到春时别恨生，渭城朝雨裛轻尘。","自家飞絮犹无定，不解迎人只送人。"]},{"t":"集古 惜春","f":"七言绝句","c":["自有林亭不得闲，长安豪贵惜春残。","晚来风起花如雪，为问无情岁月看。"]},{"t":"集古 春望","f":"七言绝句","c":["半似羞人半忍寒，风和时拂玉栏干。","门前不见归轩迹，强把花枝冷笑看。"]},{"t":"集古 寒食夜雨","f":"七言绝句","c":["风景依稀似去年，鸟啼花发柳含烟。","夜深斜搭鞦韆索，独向檐床看雨眠。"]},{"t":"集古 早行","f":"七言绝句","c":["一声歌尽各东西，花外烟濛月渐低。","马上政吟归去好，山山树里鹧鸪啼。"]},{"t":"集古 过友人别墅","f":"七言绝句","c":["少游京洛共红尘，依旧琼林照映人。","且向白云求一醉，麻衣草坐亦终身。"]},{"t":"集古 其一 不遇","f":"七言绝句","c":["来往风尘共白头，谁人肯向死前休。","直教桂子落坟上，富贵何尝润髑髅。"]},{"t":"集古 其二 不遇","f":"七言绝句","c":["岂有文章动圣君，欲将书剑学从军。","平生名利关身者，执戟官资笑子云。"]},{"t":"集古 隐居","f":"七言绝句","c":["此去秦关路几多，中原无鹿海无波。","荷蓑不是人閒事，造物小儿如子何。"]},{"t":"集古 访隐者不遇","f":"七言绝句","c":["忽闻春尽强登山，却笑孤云未是闲。","惆怅仙翁何处去，寻真不见又空还。"]},{"t":"集古 怀韩居士","f":"七言绝句","c":["乌巾年少归何处，陵谷依然世自移。","上天下地鹤一只，还在人閒人不知。"]},{"t":"集古 古道人","f":"七言绝句","c":["鹤骨飘飘紫府仙，香风引到大罗天。","无人寂寂春山路，洞在清溪何处边。"]},{"t":"集古 游仙","f":"七言绝句","c":["雾为襟袖玉为冠，委佩低簪彩仗閒。","上界真人足官府，不如归去旧青山。"]},{"t":"集古 李道者","f":"七言绝句","c":["麻衣年少雪为颜，闻说经旬不启关。","弄玉已归萧史去，洞门深锁碧窗寒。"]},{"t":"集古 其一 仙庙","f":"七言绝句","c":["桂泠松香十里閒，水晶如意玉连环。","年年笑伴皆归去，门对寒流雪满山。"]},{"t":"集古 其二 仙庙","f":"七言绝句","c":["殿台浑不似人寰，花态娇羞月思闲。","高坐寂寥尘漠漠，秋风落叶满空山。"]},{"t":"集古 女仙台","f":"七言绝句","c":["上清真子玉童颜，石座苔花自古班。","云雨今归何处去，受人祭享占人山。"]},{"t":"集古 听琴","f":"七言绝句","c":["蝉鬓慵梳倚帐门，抱琴花夜不胜春。","不应更学文君去，拟作梁园坐右人。"]},{"t":"集古 重九日","f":"七言绝句","c":["二十馀年别帝京，可能朝市污高情。","秋光何处堪消日，漫绕东篱嗅落英。"]},{"t":"集古 九日戏幕宾","f":"七言绝句","c":["一任斜阳送客愁，边鸿不到水南流。","自从身逐征西府，破帽多情却恋头。"]},{"t":"集古 晚菊","f":"七言绝句","c":["白露寒花自绕篱，从他桃李笑开迟。","一年秋色吟中过，门外重阳过不知。"]},{"t":"集古 十日对菊","f":"七言绝句","c":["篱菊香寒晚吹笙，可怜荣落在朝昏。","浮生也共花无别，不受阳和一点恩。"]},{"t":"集古 梅","f":"七言绝句","c":["我今移尔满庭栽，不向东风怨未开。","回首看花花欲尽，北人初识越人梅。"]},{"t":"集古 落梅","f":"七言绝句","c":["每到花时把酒杯，暮天何处笛声哀。","纵然一夜风吹去，不恨彫零却恨开。"]},{"t":"集古 塞上","f":"七言绝句","c":["古沟芳草起寒云，断续鸿声到晓闻。","万里江山今不闭，死生同恨旧将军。"]},{"t":"集古 登楼","f":"七言绝句","c":["东池送客醉年华，独倚危楼四望赊。","日暮鸟啼人散尽，轻风细雨落残花。"]},{"t":"集古 花期不赴","f":"七言绝句","c":["云泥岂合得相亲，还把闲吟慰病身。","一种是春长富贵，有愁人有不愁人。"]},{"t":"集古 醉眠","f":"七言绝句","c":["糁径杨花铺白毡，日西铺在古苔边。","满山明月东风夜，留与游人一醉眠。"]},{"t":"集古 山中偶得","f":"七言绝句","c":["弃掷功名脱屣閒，东风吹雨过青山。","行人莫话金章贵，久许孤云作往还。"]},{"t":"集古 夜饮","f":"七言绝句","c":["虚榻吟窗更待谁，酒无多少醉为期。","明朝骑马摇鞭去，会有求闲不得时。"]},{"t":"下太行","f":"七言绝句","c":["山中日日伴云閒，不见閒云只见山。","君去试从山下望，青山却在白云间。"]},{"t":"寄别","f":"七言绝句","c":["马蹄踏破乱山青，送客风回酒半醒。","归客莫将云外指，大都一十五长亭。"]},{"t":"香梅二首 其一","f":"七言绝句","c":["被谁说破梦中梅，应有罗浮倒挂来。","祇为怕愁贪睡后，返魂才向北枝开。"]},{"t":"香梅二首 其二","f":"七言绝句","c":["一枝潇洒陇头香，分付新愁竹叶觞。","纸帐不须寻短梦，天涯倦客已无肠。"]},{"t":"集古十二首 其五","f":"七言绝句","c":["谁家红袖倚江楼，白袷行人又远游。","今夜不知何处泊？","青山万里一孤舟。"]},{"t":"寄赵庭干二首 其一","f":"七言绝句","c":["试将小录问同年，风采依稀坠目前。","三十一人今鬼录，与君虽在各华颠。"]},{"t":"寄赵庭干二首 其二","f":"七言绝句","c":["君还携幼去幽燕，我向荒山学种田。","千里暮鸿行断处，碧云容易作愁天。"]},{"t":"赠张仲一","f":"七言律诗","c":["丹凤衔书下九霄，山城和气动民谣。","久潜龙虎声相应，未戮鲸鲵气尚骄。","万里江山归一统，百年人事见清朝。","天教老眼观新化，白发那堪不肯饶！"]}]};